(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["2-9"] = [{"a": [221], "v": 1, "p": 454, "ev": 1, "ep": 456, "sid": 455, "t": "قوله - عز وجل -:\n﴿وَلَا تَنكِحُواْ ٱلۡمُشۡرِكَٰتِ حَتَّىٰ يُؤۡمِنَّۚ وَلَأَمَةٞ مُّؤۡمِنَةٌ خَيۡرٞ مِّن مُّشۡرِكَةٖ وَلَوۡ أَعۡجَبَتۡكُمۡۗ وَلَا تُنكِحُواْ ٱلۡمُشۡرِكِينَ حَتَّىٰ يُؤۡمِنُواْۚ وَلَعَبۡدٞ مُّؤۡمِنٌ خَيۡرٞ مِّن مُّشۡرِكٖ وَلَوۡ أَعۡجَبَكُمۡۗ أُوْلَٰٓئِكَ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَٱللَّهُ يَدۡعُوٓاْ إِلَى ٱلۡجَنَّةِ وَٱلۡمَغۡفِرَةِ بِإِذۡنِهِۦۖ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ﴾⟪2:221⟫\nالآية (221) - سورة البقرة.\nالنكاح اسم للعقد، واستعير للجماع بدلالة أن عامة أسماء الجماع كنايات، وأنهم يتحاشون النكاح من التصريح بذكر الجماع، وآلاته، كما يتحاشون من إظهاره حتى سموا ذلك العضو \" السوءة \"، ولم يستعيروا اسم الجماع وآلاته إلا فيما يقصدون به سبعة، نحو: شوربه إذا خجله وجعله بحيث كأنه أبدى شواره، والشوار مع ذلك كناية للفرح، وبهذا يعلم أن النكاح وفي اللغة مستعار للجماع، والنهي عن نكاح المشركات عام فيمن ليس من أهل الكتابة ولم يدخل في ذلك أهل الكتاب لقوله: ﴿وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ﴾⟪5:5⟫،\nفإن قيل: فقد قال تعالى: ﴿لَّا تَجِدُ قَوۡمٗا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ يُوَآدُّونَ مَنۡ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ﴾⟪58:22⟫، الآية، والنكاح يجب المودة لقوله: ﴿أَنۡ خَلَقَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا لِّتَسۡكُنُوٓاْ إِلَيۡهَا وَجَعَلَ بَيۡنَكُم مَّوَدَّةٗ وَرَحۡمَةًۚ﴾⟪30:21⟫، وقد نهانا عن مودتهم، فيجب أن لا نواصلهم!\nقيل: المودة النهي عنها هي الدينية لا المودة النفعية أو الشهوية، فإنا إذا أوددناهم لنفع ما، فإنما نود النفع كمودتنا لذمي يعيننا على مدافعة المشركين، فقوله: ﴿يُوَآدُّونَ مَنۡ حَآدَّ ٱللَّهَ﴾⟪58:22⟫ عنى بها المودة الدينية،\nفإن قيل: ما قلت يقتضي أن يجوز نكاح المشركات؟ قيل المشرك مادام مشركا، فنفسه مباحة، والمشركة غير مالكة لنفسها، وفي قوله: ﴿وَلَعَبۡدٞ مُّؤۡمِنٌ خَيۡرٞ مِّن مُّشۡرِكٖ﴾⟪2:221⟫ إشارة مجملة إلى فضل العبد المؤمن على العبد المشرك وبيان فضيلته يحتاج إلى مقدمة، وهي أن الشيئين\n⟦1:455⟧\nإذا تشكك أيهما أفضل، أحدث كل واحد منهما مع ضد الآخر أنهما هو المؤثر، فحكمت له مثاله أن من شك في العلم والغنى أيهما أفضل؟ نقول: انظر هل الغنى مع الجهل أفضل؟ أم الفقر مع العلم؟ فإذا علمت أن الفقر مع العلم أفضل من الجهل مع الغنى علمت أن العلم أفضل من الغنى، فإذا ثبت ذلك، فالعبد هو الذي ملك منافعه مدة، والحر هو الذي لم يملك منافعه، والمؤمن هو المستحق للثواب الدائم، والمشرك هو المستحق للعقاب الدائم، فينظر هل من ملك منافعه مدة ثم أثبت دائما أفضل؟ أم من لم يستحق منافعه مدة وتعاقب دائما؟ فإذا علمنا أن الأول خير، علمنا أن العبد المؤمن خير من الحر المشرك، ونبه بقوله: ﴿وَلَوۡ أَعۡجَبَتۡكُمۡۗ﴾⟪2:221⟫ أن الاعتبار بإعجابكم، فليس الإعجاب إلا من ثمرة الجهل بحقيقة الشيء والجهل لا يوجب حكما، فإذن لا اعتبار بإعجابكم، ونبه - عز وجل - على تحريم مواصلة المشركين بقوله: ﴿أُوْلَٰٓئِكَ يَدۡعُونَ إِلَى ٱلنَّارِۖ﴾⟪2:221⟫ أي إلى الأفعال الوجبة للنار، وواجب اجتناب الداعي إلى النار الحامل عليها فواجب مجانبتهم إذن، وعلى هذا قال - عليه السلام - \" لا تترائى ناراهما \"، ثم قال: ﴿وَٱللَّهُ يَدۡعُوٓاْ إِلَى ٱلۡجَنَّةِ﴾⟪2:221⟫، والداعي إلى الجنة واجب إتباعه، وعلى هذا دل قوله - عز وجل - حكاية عمن أخبر عنه: ﴿مَا لِيٓ أَدۡعُوكُمۡ إِلَى ٱلنَّجَوٰةِ وَتَدۡعُونَنِيٓ إِلَى ٱلنَّارِ﴾⟪40:41⟫، تدعونني وبإذنه، أي بعلمه وأمره وآياته وحججه ودلائله العقلية والشرعية من أنكم إذا فعلتم ذلك، فأنتم أهل لرجاء التذكر وحقيقة التذكر الاستدراك عن نسيان أو غفلة لما استثبته القلب ..\nإن قيل: إلى أي شيء أشار بهذا التذكر؟\nقيل: إن الله عز وجل - ركز فينا بالفطرة معرفته ومعرفة ألائه، والإنسان باستفادة العلم يتذكر ما ركز فيه، فهذا معنى التذكر وقال قوم: معرفة الله عز وجل، ومعرفة الآية تذكر، ومن دفع عن قلبه الأغشية بذكر ما قال الله عز وجل له ودل عليه بقوله عز وجل: ﴿وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِيٓ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّيَّتَهُمۡ﴾⟪7:172⟫ الآية، قالوا: وقد عرفنا الطريق الذي به يتوصل إلى هذا التذكر بقوله: «إن الله يأمر بالعدل\n⟦1:456⟧\nوالإحسان وإيتاء ذي القربى وينهى عن الفحشاء والمنكر والبغي يعظكم لعلكم تذكرون» فبين أنكم إذا فعلتم ذلك رجوتم تذكر هذه الحالة، وقد قيل: \" الرجا من الله واجب \"، بمعنى أنه إذا رجانا حقق رجاءنا، وهذه مسألة لا يمكن تصورها لمن يبلغها بتعاطي هذه الأفعال التي شرطه الله عز وجل - فلذلك لعلها صعب إدراكها لنا."}, {"a": [222], "v": 1, "p": 456, "ev": 1, "ep": 458, "sid": 457, "t": "قوله - عز وجل :\n﴿وَيَسۡـَٔلُونَكَ عَنِ ٱلۡمَحِيضِۖ قُلۡ هُوَ أَذٗى فَٱعۡتَزِلُواْ ٱلنِّسَآءَ فِي ٱلۡمَحِيضِ وَلَا تَقۡرَبُوهُنَّ حَتَّىٰ يَطۡهُرۡنَۖ فَإِذَا تَطَهَّرۡنَ فَأۡتُوهُنَّ مِنۡ حَيۡثُ أَمَرَكُمُ ٱللَّهُۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ﴾⟪2:222⟫\nالآية (222) - سورة البقرة.\nالمحيض: وقت الحيض وموضعه، وقد قيل: يقال للحيض محيض، على أن المصدر في هذا الباب يجئ على (مفعل)، نحو: معاش ومعاد، وقول الشاعر:\nلا يستطيع بها الفراد مقيلا\nفالأظهر أنه مكان وإن كان قد قيل هو مصدر، وقيل ما في ترك مكال ومكيل، أي كيل وهو أيضا محتمل، والحيض هو الدم الخارج من الرحم على وصف مخصوص في وقت مخصوص ويتعلق به منع الصلاة، والصوم، وحظر الجماع، وانقضاء العدة، واجتناب دخول المسجد ومس المصحف، وقراءة القرآن، وأن تصير المرأة به في الابتداء مكلفة، والاعتزال: العدول عن الشيء، وأصله من العزل، وهو صرف العامل عن عمله، ومنه قيل الأعزل للعازل عن الحرب لعدم السلاح، وللدابة المائل ذنبها والعزلاء تأنيث الأعزل، وشبه مخرج الماء إذا فتح عن فقد سلاحه، والسماك الأعزل سمي بذلك لافتقاده الكوكب الذي يصور بصورة الرمح للسماك الأخر ..\n، والأذى: اسم لما ينال النفس منه\n⟦1:457⟧\nمكروه، ولهذا سمي الله تعالى الكلام المكروه أذى، فقال: ﴿وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِينَ أَشۡرَكُوٓاْ أَذٗى كَثِيرٗاۚ﴾⟪3:186⟫ وما ينال الإنسان من مكروه المطر أذى في قوله تعالى: ﴿إِن كَانَ بِكُمۡ أَذٗى مِّن مَّطَرٍ﴾⟪4:102⟫ ولما كان الناس في مجامعة المرأة في حال الحيض بين إفراط وتفريط فإن اليهود كانوا إذا حاضت المرأة لم يؤاكلوها ولم يجتمعوا معها في البيوت وبعض النصارى لم يتحاش من مجامعتها، فسئل - عليه السلام -، فقال تعالى: ﴿هُوَ أَذٗى﴾⟪2:222⟫ تنبيها أن العقل يقتضي تجنبه كأنه قيل: الحيض أذى وكل أذى يتحاشى منه والحيض يتحاشى منه، ولما كان الإنسان قد يتحمل الأذى ولا يراه محرما صرح بتحريمه بقوله: ﴿فَٱعۡتَزِلُواْ ٱلنِّسَآءَ فِي ٱلۡمَحِيضِ﴾⟪2:222⟫\nإن قيل: فأي أذى هو؟\nقيل: إما باعتبار مجرد الشرع، فإثم وإما بالاعتبار الطبي، فإن الدم الذي يخرجه الرحم يفسد البدن الذي منه الحيوان، ويكون له بخارات ممرضة لأبدان متشمميها يعرض للمرض ولما كان الاعتزال قولا مشتركا ويكنى به عن العدول عنها عند الفراغ وعن مجانبة ذلك الموضع وعن مجانبتها رأسا، قال تعالى: ﴿وَلَا تَقۡرَبُوهُنَّ﴾⟪2:222⟫ ليدل باللفظتين الكنايتين على مجانبة مباضعتها، وعلى جواز التمتع بها منها دون الفرج المدلول عليه بقول النبي - عليه السلام: \" اصنعوا كل شيء إلا الجماع \" ولما كان لفظ ﴿يَطۡهُرۡنَۖ﴾⟪2:222⟫ يقال فيما كان طاهرا بنفسه وفيما كان يتطهر، نبه بقوله: ﴿فَإِذَا تَطَهَّرۡنَ﴾⟪2:222⟫ أنه لم يرد إلا الطهارة عن تطهر وتؤكد ذلك قراءة من قرأ: ﴿حَتَّىٰ يَطۡهُرۡنَۖ﴾⟪2:222⟫ فدل ذلك أن لا يصح\n⟦1:458⟧\nوطؤها ما لم تغتسل، وقوله: ﴿فَإِذَا تَطَهَّرۡنَ﴾⟪2:222⟫ دل أن ذلك شرط في إباحتها وأن لا يصح وطؤها إلا بانقطاع دمها، وقوله: ﴿فَأۡتُوهُنَّ مِنۡ حَيۡثُ أَمَرَكُمُ ٱللَّهُۚ﴾⟪2:222⟫ إشارة إلى مراعاة كل ما أمر به من أحكام النكاح ومجانبة المحاشي، يعني الموضع المكروه وغير ذلك من الأمور التي أمر بها، ثم قال: ﴿إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ﴾⟪2:222⟫ تنبيها أن من كان منه شيء من ذلك، فحق عليه أن يتوب ويتطهر من بعد، والتطهر عام في استعمال الماء، وتطهر القلوب من الذنوب والتوبة اجتناب الذنب والتطهر عمل الصالحات، وجعل التوبة مقدمة على التطهير تنبيها أن اجتناب القاذورات مدرجة إلى فعل الخيرات، وعظم أمر المتطهرين حيث جعلهم محبوبيه، وروي خريم بن ساعدة قال: يا رسول الله: من الذين قال الله - عز وجل - فيهم ﴿فِيهِ رِجَالٞ يُحِبُّونَ أَن يَتَطَهَّرُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُطَّهِّرِينَ﴾⟪9:108⟫؟\nفقال عليه السلام:\n\" نعم الرجل منهم خريم \" ويدل على إرادة هذا المعنى بالتطهر قوله: ﴿إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ أَهۡلَ ٱلۡبَيۡتِ وَيُطَهِّرَكُمۡ تَطۡهِيرٗا﴾⟪33:33⟫"}, {"a": [223], "v": 1, "p": 458, "ev": 1, "ep": 460, "sid": 459, "t": "قوله - عز وجل:\n﴿نِسَآؤُكُمۡ حَرۡثٞ لَّكُمۡ فَأۡتُواْ حَرۡثَكُمۡ أَنَّىٰ شِئۡتُمۡۖ وَقَدِّمُواْ لِأَنفُسِكُمۡۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُم مُّلَٰقُوهُۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ﴾⟪2:223⟫ سورة البقرة الآية (223) ..\nالفرق بين الحرث والزرع أن الحرث إلقاء البذور وتهيئة الأرض، والزرع مراعاته وإنباته، ولهذا قال تعالى: ﴿أَفَرَءَيۡتُم مَّا تَحۡرُثُونَ ۝ ءَأَنتُمۡ تَزۡرَعُونَهُۥٓ أَمۡ نَحۡنُ ٱلزَّٰرِعُونَ﴾⟪56:63-64⟫ فأثبت لهم الحرث، ونفى عنهم الزرع، وقد جعل الله تعالى النساء محترثا للرجل، وجعل له قوة النكاح حفظا للنسل، ولولا طلب\n⟦1:459⟧\nالنسل لما رخص العقل في الجماع لما يجلب من ذبول البدن وإضعاف البصر، مع أنه ليس بضروري للإنسان كالجوع والعطش، لكن استحسن ما استحسن منه لطلب النسل المدعو إليه بقوله - عليه السلام: (تناكحوا تكثروا)، ولذلك قيل في الحكمة: \" خير النساء الولود الولود، وشرها العقيم \"،\nوحرم إتيان الرجال على كل حال والنساء في محاشهن إذا لم يكن محرما ما سماه - عليه السلام - \" اللواطة الصغرى \" وقيل لأمير الآمؤنين: كيف ترى النساء يؤتين في أدبارهن؟ فقال: \" سفلت سفل الله بك \" ثم تلا قوله تعالى: ﴿أَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ﴾، وقوله: ﴿فَأۡتُواْ حَرۡثَكُمۡ أَنَّىٰ شِئۡتُمۡۖ﴾⟪2:223⟫ أي: كيف وأين بعد أن لا يتجاوز به الحرث وأعاد لفظ الحرث، ولم يقل: فأتوه، ليراعى المعنى المقصود بذلك، لئلا يتوهم ما يتصوره قدم لم يتعمقوا النظر وإنما قال: \" أنى \" تنبيها على كذب اليهود حيث زعموا أن المرأة إذا لم تؤت مستقبلة يأتي الولد ذا خيل أي أحول وقوله عقيب ذلك: ﴿وَقَدِّمُواْ لِأَنفُسِكُمۡۚ﴾⟪2:223⟫، هو أن الله إذا أطلق أمرا من الشهوات الدنيوية لا يخلى ذكره من الحث على مراعاة العقبى والتقوى، لئلا يلحق الإنسان غفلة عما خلق لأجله وقول عطاء: هو التسمية عند الجماع، وقول ابن عباس: هو الطلب للولد على سبيل المثال لا أنه لم يرد سوى ذلك ﴿وَٱعۡلَمُوٓاْ أَنَّكُم مُّلَٰقُوهُۗ﴾⟪2:223⟫ أي صائرون إليه.\nواللقاء يقال في المحسوس والمعقول يقال: لقى إثما وجهدا، قال الله - عز وجل: ﴿وَمَن يَفۡعَلۡ ذَٰلِكَ يَلۡقَ أَثَامٗا﴾⟪25:68⟫.\n⟦1:460⟧"}, {"a": [224], "v": 1, "p": 460, "ev": 1, "ep": 461, "sid": 461, "t": "قوله - عز وجل:\n﴿وَلَا تَجۡعَلُواْ ٱللَّهَ عُرۡضَةٗ لِّأَيۡمَٰنِكُمۡ أَن تَبَرُّواْ وَتَتَّقُواْ وَتُصۡلِحُواْ بَيۡنَ ٱلنَّاسِۚ وَٱللَّهُ سَمِيعٌ عَلِيمٞ﴾⟪2:224⟫\nالآية (224) - سورة البقرة.\nاليمين أصله العضو، واستعير للحلف لما جرت به العادة في تصافح المتعاقدين، وعلى هذا قال الشاعرة:\nقلت كفى لك رهن بالرضى\n....\nفوضع الكف موضع اليمين\nوالعرضة ما يجعل معترضا بين شيئين، فيتصور تارة بالحائل فقيل معناه: لا تجعلوا لفظ الله مانعا من أن تبروا وتتقوا، نحو: ﴿وَلَا يَأۡتَلِ أُوْلُواْ ٱلۡفَضۡلِ مِنكُمۡ وَٱلسَّعَةِ أَن يُؤۡتُوٓاْ أُوْلِي ٱلۡقُرۡبَىٰ﴾⟪24:22⟫ وذلك أنه كان أحدهم لا يبر، فإذا عوتب قال: حلفت، وعلى هذا قال الشاعر:\nتسلف الجار شربا وهي حاتمة\n....\nولا يبيت على أعناقهم قسم\nولأجل ذلك قال - عليه السلام:\n\" إذا حلف أحدكم على شيء، فرأى غيره خيرا منه فليأت الذي هو خير وليكفر عن يمينه \"، وقد تصور العرضة بصورة المبتذل، نحو: (لا تجعليني عرضة للوائم)، ومعناه: لا تجعلوا لفظ الله مبتذلا لليمين، لأن تبروا، فيكون ذلك نهيا عن كثرة الحلف المذموم بقوله: ﴿وَلَا تُطِعۡ كُلَّ حَلَّافٖ مَّهِينٍ﴾⟪68:10⟫\nفإن قيل: وما تقدير \" أن تبروا \" على هذا؟ قيل: يجوز أن يكون متعلقا باليمين، وتقديره: أن لا تبروا\n⟦1:461⟧\nلأنك تقول، حلفت أن تخرج، فيحذف \" لا \" أمنا من الاشتباه في الإثبات، إذ في الإثبات، فقال: حلفت لأخرجن أو لأخرجن، وقال بعضهم: معناه: \" نهاكم أن تكثروا الأيمان لأن تبروا \"، أي إنما نهاكم عن ذلك لتكونوا بررة أتقياء مصلحين، كما قال:\n﴿كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ﴾⟪3:110⟫ الآية، وقيل معناه: لا تجعلوا لفظ الله مبتذلا لليمين لأن تبروا بالحلف به، وتتقوا المأثم وتصلحوا، والمعنى لا تبتذلوه لفعل الخيرات، فكيف للشر تنبيها أن الحلف بالله مكروه ما استغنى عنه، ونبه بقوله: ﴿وَٱللَّهُ سَمِيعٌ عَلِيمٞ﴾⟪2:224⟫ أنه عارف بالمقاصد ..."}, {"a": [225], "v": 1, "p": 461, "ev": 1, "ep": 463, "sid": 462, "t": "قوله - عز وجل -:\n﴿لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتۡ قُلُوبُكُمۡۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ﴾⟪2:225⟫\nالآية (225) - سورة البقرة.\nاللغو: المطروح الذي لا يفيد من الكلام، يقال: ألغى في كلامه، ولغا، وقد يقال في غيره تشبيها، كقول الشاعر:\nكما ألغيت في الدية ألحوارا\nويكني باللغو عن القبيح من الكلام، وأصله من لغي العصافير، واختلف في اللغو من اليمين، فقال ابن عباس: هو الحلف بالشيء يظن أنه صادق فيه وهو بخلافه، وقال ابن جبير: هو اليمين علي الحرام لا يؤاخذ الله بتركه، وقال: هو بغضهم اليمين التي يحنثو فيها صاحبها سهوا، وقالت عائشه:\n⟦1:462⟧\nوقد روي عن النبي - صلى الله عليه وسلم - إنه قول الرجل: (لا والله) و (بلى والله) على سبيل العجلة لا على القصد،\nوإليه ذهب الشافعي، وقال أبو حنيفة: لغو اليمين كالغموس في أنه لا تجب فيهما الكفارة، ولكن الغموس أن يحلف ويعلم أن الأمر خلافه، فيعظم معصيته واللغو أن لا يعلم، بل يظن فلا تقع المؤاخذة به، وقوله:\n﴿وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتۡ قُلُوبُكُمۡۗ﴾⟪2:225⟫ هو أعلم من قوله: ﴿وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلۡأَيۡمَٰنَۖ﴾⟪5:89⟫ وذاك أنه لما كان القلب يعبر به عن الجزء الذي به المعرفة والفكر ويجري من سائر أجزائه مجرى الراعي من المراعي، ونبه بقوله: ﴿بِمَا كَسَبَتۡ قُلُوبُكُمۡۗ﴾⟪2:225⟫ أن الاعتدال به دون غيره من الجوارح، حتى إن كل فعل لا يكون عنه وبه سهوا أو خطأ متجافى عنه، ولهذا قال- عليه السلام- \" إن في الإنسان مضغة إذا صلحت صلح سائر الجسد، وإذا فسدت فسد سائر الجسد \"، وقال: \" إذا طاب قلب المرء طاب جسده \"، وقال: \" إن الله تعالى لا ينظر إلي صوركم ولا إلى أموالكم وإنما ينظر إلي قلوبكم وأعمالكم \".\nوالحلم وإن كان منا هو إمساك القوة العصبية المقتضي للعفو، وهو إذا استعمل في الله لا يراد به إلا العفو عن المذنب دون حدوت حالة وتجدد أمر عليه- تعالى الله عن ذلك علوا كبيرا.\n⟦1:463⟧"}, {"a": [226], "v": 1, "p": 463, "ev": 1, "ep": 465, "sid": 464, "t": "قوله - عز وجل -:\n﴿لِّلَّذِينَ يُؤۡلُونَ مِن نِّسَآئِهِمۡ تَرَبُّصُ أَرۡبَعَةِ أَشۡهُرٖۖ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ﴾⟪2:226⟫\nسورة البقرة الآية (226) ..\nالتربص: انتظار مجئ وقت، يقال: تربصت به، وربصت به، قال الله- عز وجل: ﴿فَتَرَبَّصُواْ بِهِۦ حَتَّىٰ حِينٖ﴾⟪23:25⟫، وقيل في هذا الأمر ربصه، والفئ: الرجوع من مكان إلى مكان، ولم يسم من الظل فيأ إلا الراجع منه، وسمى العتمة فيألفيئه من قوم إلى قوم، وقول الشاعر:\nأرى المال أفياء الظلال عشية\nأي المال هو الفئ الذي هو بعض الظلال تنبيها علي ما قال الآخر:\nإنما الدنيا كظل زائل.\nواللإيلاء: الحلف المقتضي للتقصير في الأمر الذي يحلف عليه من قوله عز وجل: ﴿لَا يَأۡلُونَكُمۡ خَبَالٗا﴾⟪3:118⟫، ﴿وَلَا يَأۡتَلِ أُوْلُواْ ٱلۡفَضۡلِ مِنكُمۡ﴾⟪24:22⟫ وصار الإيلاء في الشرع الحلف المانع من جماع المرأة، وهو أن الرجل كان إذا لم يرد المرأة ولا يحب أن يتزوجها غيره، يحلف أن لا يجامعها، ويتركها كذلك، لا إيما، ولا ذات بعل، فأراد الله أن يجعل لها مخرجها فحكم بهذه الآية، إلا أنه اختلف في أي لفظ من الأيمان يكون الإيلاء، وعلى أي وجه يعتبر ترك جماعها، وأي يمين من الإيلاء تلزم فيه الكفارة؟ وكم مدة الإيلاء؟ وما عزم الطلاق؟ وما ألفئ؟ ومن الذي لإيلأئه حكم؟ أي امرأة لها حكم\n⟦1:464⟧\nالإيلاء؟ أما أي يمين هو؟ فعند أبي حنيفة جميع الأيمان حلفا بالله عز وجل، كان، أو طلاقا أو عتاقا أو نذرا، وبه قال الشافعي في الحدود، وقال مالك: \" لا يكون موليا إلا بالحلف بالله -عز وجل- \"، وبه قال الشافعي في القديم، وروي عن ابن عباس أن كل يمين منعت من الجماع في فإيلاء، وأما على أي وجه يعتبر ترك جماعها، فعند علي وابن عباس والحسن وعطاء إذا حلف أن لا يجامعها على وجه الضرار والغضب، فأما إن لم يكن على ذلك نحو أن يحلف أن لا يجامعها في وقت إرضاعها الولد لئلا يضر بالولد، فلا يكون موليا، وقال الحسن: \" إذا حلف أن لا يجامعها في هذا البيت، ثم ترك جماعها أربعة أشهر فإيلاء \"، وم ال ابن المسيب: \" إذا حلف أن لا يكلمها فإيلاء أيضا \"، وقال ابن عمر: \" إذا هجرها من غير يمين يكون موليا \"،، وأما أي يمين من الإيلاء يلزم فيه الكفارة، فهي كل يمين بالله- عز وجل- وأما المدة: فمنهم من قال: أكثر من أربعة أشهر أي قدر كان، لأنه جعل لها المطالبة بعد ذلك، ولأنه قال: ﴿فَإِن فَآءُو﴾⟪2:226⟫ ولم يحصل بعد المدة، وفي المدة، ومنهم من قال: أربعة أشهر فصاعدا، هو بعض الظلال تنبيها على ما قاله الأخر: وإن حلف على أقل من أربعة أشهر لا يكون موليا وإن تركها أربعة أشهر على قول عامة الفقهاء، وقال ابن مسعود وقتادة: يكون ووليا، ولا خلاف أنه إذا لم يتركها أربعة أشهر لا يكون موليا وأما عزم الطلاق، فعند عمر، وعثمان، وابن عباس، وابن مسعود أنه انقضاء الأربعة أشهر، وأنها تبين بتطليقه، وعند الشافعي أن للمرأة مطالبتها بعد الأربعة الأشهر ، ويجب عليه أن حق أو يراجع ولا يستمهل أكثر من يوم، فإن طلقها تطليقة تكون رجعية، ولو عفت عن ذلك في الوقت، فلها أن تطلب بعد ذلك متى أرادت، وأما ألفئ فظاهره يقتضي الفئ بالقول، كالمراجعة إلا أنهم أجمعوا أنه إذا أمكنه لم يكن إلا بالجماع، فأما إذا كان محجوبا أن محبوسا عنها، فقد قيل فيه بالقول، وأما من الذي لإيلائه حكم؟، فكل من صح طلاقه حرا كان أو عبدا مسلما كان أو ذميا حرة كانت تحبه أو أمة، وأبو حنيفة اعتبر بالمرأة كالطلاق، ومالك اعتبر بالرجل دونها، وقال بعض الفقهاء: الإيلاء لذمي، والآية تقتضي خلاف قوله: وأما أي امرأة لها حكم الإيلاء، فكل امرأة يصح طلاقها يصح الإيلاء منها، مسلمة كانت أو ذمية، حرة كانت أو أمة، صغيرة كانت أو كبيرة، لكن ليس للصغيرة المطالبة حتى يمكن مجامعتها وتأتي عليها المدة المضروبة و \" من \" في قوله:\n⟦1:465⟧\n﴿مِن نِّسَآئِهِمۡ﴾⟪2:226⟫ تعتبره الفقهاء أنه متعلق بقوله: ﴿يُؤۡلُونَ﴾⟪2:226⟫ حتى كثر في كلامهم \" ألي فلان من امرأته \"، كقولهم: \" ظاهر منها \"، وذلك غير ممتنع وإن كان قد ذكر بعض أهل اللغة أن تقدير الكلام: (لهم من نسائهم تربص أربعة أشهر) ودل بقوله: ﴿فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ﴾⟪2:226⟫ أن المولى في إيلائه مخطئ وإثم، وأنه يستحق العفو عما ارتكبه بفيئه ..\nقوله- عز جل:"}, {"a": [227], "v": 1, "p": 465, "ev": 1, "ep": 465, "sid": 466, "t": "﴿وَإِنۡ عَزَمُواْ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ﴾⟪2:227⟫ الآية: (227) - سورة البقرة.\nدواعي الإنسان إلى الفعل على مراتب أولها السابح، ثم الخاطر، تم التخيل والتفكر فيه، ثم الإرادة، ثم الهمة، ثم العزم، فالهمة إجماع من النفس على الأمر وإزماع عليه، والعزم هو العقد على إمضائه، ولهذا قال- عز وجل- ﴿فَإِذَا عَزَمۡتَ فَتَوَكَّلۡ عَلَى ٱللَّهِۚ﴾⟪3:159⟫، ويقال: (مالفلان عزمه) أي عقد على إمضائه ...\nويقال: المعود عزائم تصورا أنك قد عقدت على الشيطان أو الداء أن يمضي إراداتك فيما سميته، والطلاق: تخلية عن وثاق أو داء أو انقباض وإمساك، ومنه: \" طلقت المرأة عند الولادة وبالتخليه عن الوثاق شبه الطلق في العدو، ورجل طلق الوجه وطلق اليدين، وأما عزيمة الطلاق، فقد تقدمت، ونبه تعالى بقوله: ﴿سَمِيعٌ عَلِيمٞ﴾⟪2:227⟫ أنه عارف بضميره ومقاله في إيلائه وتطليقه ..."}, {"a": [228], "v": 1, "p": 465, "ev": 1, "ep": 471, "sid": 466, "t": "قوله- عز وجل:\n﴿وَٱلۡمُطَلَّقَٰتُ يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٖۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكۡتُمۡنَ مَا خَلَقَ ٱللَّهُ فِيٓ أَرۡحَامِهِنَّ إِن كُنَّ يُؤۡمِنَّ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَٰلِكَ إِنۡ أَرَادُوٓاْ إِصۡلَٰحٗاۚ وَلَهُنَّ مِثۡلُ ٱلَّذِي عَلَيۡهِنَّ بِٱلۡمَعۡرُوفِۚ وَلِلرِّجَالِ عَلَيۡهِنَّ دَرَجَةٞۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ﴾⟪2:228⟫\nسورة البقرة الآية (228) ...\nقال الخليل: قرأت المرأة: رأت الدم، وأقرأت: حاضت، وصارت ذات قرء، والقرء في الحقيقة اسم للدخول في الحيض عن طهر، ولما كان اسما للأمرين الطهر والحيض المتعقب له أطلق على كل\n⟦1:466⟧\nواحد منهما، لأن عادة العرب أن كل اسم موضوع لمعنيين معا يطلق على كل واحد منهما إذا انفرد، كالمائدة هي للخوان والطعام، وقد سمي كل واحد منهما بانفراده مائدة، وعلى ذلك الظعينة والكأس والراوية، فكذلك القرؤ، وليس هما اسما للطهر مجردا بدلالة أن الطاهر التي لم تر الدم لا يقال لها ذات قرء، وكذا الحائض التي استمر بها الدم، والنفساء لا يقال لهما ذلك، فقوله: ﴿وَٱلۡمُطَلَّقَٰتُ يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٖۚ﴾⟪2:228⟫، أي ثلاثة دخول من الطهر في الحيض وليس حقيقة هذا إلا ما قاله الشافعي دون ما قاله غيره في أنها إذا رأت الدم ثلاث مرات، فقد انقضى عدتها، وجعل غيره حصول ثلاثة أطهار تتعقبها ثلاث حيض،\nفإن قيل: قوله- عليه السلام: (دعي الصلاة أيام إقرائك) لم يرد أيام تجدد الحيض، وإنما أراد أيام الحيض كلها، قيل: ما قلته صحيح، وإنما ذلك كقولك: \" فعل كذا أيام ورود فلان، ووروده إنما كان في ساعة، فكذلك قوله: \" أيام إقرائك \"، والحدث القليل ينسب إلى الزمن الطويل، وإن وقع ذلك في بعضه، وقول أهل اللغة أن القرء من قرءا إذا جمع، وقارئ هم اعتبروا الجمع ومن زمن الطهر وزمن الحيض لاجتماع الدم في الرحم فقط، ومنه القراءة، وهو ضم الحروف والكلمات بالخروج من بعضها إلى بعض، يدلك على ذلك أنه لا يقال للحرف الواحد يتفوه به قراءة، و \" أقرأ النجم \" إذا طلع واحد وغاب آخر، وصار القرؤ مستعارا للوقت المنتظر، ومنه قال الشاعر:\nإذا هبت لقارئها الرياح\nأي لوقتها المنتظر المتعين.\nوقال أخر:\nيا رب ذي ضغن على فارض\n....\nله قرؤ كقرؤ الحائض\n⟦1:467⟧\nأي انتظار للفرصة كانتظار ذات الحيض للحيض. . . وعير ابن داود الشافعي لما جمع بين القرؤ وقريت الماء في الحوض، وقال: ألم ير أن قريت من نبات التاء، وقرأت من الهمزة، وهذا سوء ظن منه وسوء تصور، فإن أهل اللغة طريقتان في هذين اللفظين أحدهما: أنه \" قريت \" مقلوب عن قرأت، واليا ما بدل من الهمزة، كسألت، وسلت، والثاني: أنهما لغتان تقارب معنياهما تقارب ألفاظهما، وأنهما تقتضيان معنى الجمع، والبعل: النخل السارب بعزوقه، وعبر به عن الزوج، لإقامته على الزوجة للمعنى المخصوص، وحيث هي بعلة، وقيل: باعلها كقولك: جامعها، وبعل الرجل إذا دهس، فأقام مكانه كالنخل ألدي لا يبرح، وبهذا النظر، قيل لمن لا يحول لكن مكانه ما هو إلا شجر أو حجر، والبعولة جمع بعل، كالذكورة، والفحولة، والعمومة، والخؤولة، والرجل بنى عن رجل تصورا لسعيه بها، كما سميت المرأة قعيدة وعحوزا لتمكن مقعدها وعجزها من الأرض ولذلك قال الشاعر:\nأصبحت لا رجلا يغدولمطلبه\n....\nولا قعيدة بيت تحسن العملا\nوبهذا النظر سمي القوم قوما لقيامهم بالأمور، والراجل الماشي لكونه ضاربا برجله الأرض كالسائف والرامح لمن يضرب بهما، وارتحل فلان كذا لما تناوله بسعيه مما لم يسبق إليه، وترحل النهار، كقولهم: \" قام قائم الظهيرة \"، والمرجل، القدر المنتصب على رجلها، وجعل بناؤه بناء الآلات والدرجة والمرقاة والمنزلة تستعار للمحال الشرفية، وذاك أن الشرف المعقول يمثل بالمحسوس على\nوجهين، أحدهما يعتبر على طريق العلو والسفل، فتستعمل فيه الدرجة، والمرقاه، والصعود، والانحدار، والثاني على طريق التقدم والتأخر، فيستعمل فيه السبق والتخلف والمطلقات ضربان: مدخول بها، وغير مدخول بها ولا عدة عليها لقوله عز وجل: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نَكَحۡتُمُ ٱلۡمُؤۡمِنَٰتِ ثُمَّ طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمۡ عَلَيۡهِنَّ مِنۡ عِدَّةٖ تَعۡتَدُّونَهَاۖ﴾⟪33:49⟫، والمدخول بها عليها العدة،\n⟦1:468⟧\nوهي على ثلاثة أضرب:\nالحوامل: وعدتهن أن يضعن حملهن، واليائسات، واللائي لم يحضن، وعدتهن ثلاثة أشهر، وذوات الحيض: وعدتهن ثلاثة أقرؤ، وهذا الحكم إذا كانت امرأة حرة فأما إذا كانت أمة فقرآن، وفي الشهور على النصف من الحرة ...\nإن قيل: كيف استعير لفمظ الخبر للأمر في قوله: ﴿يَتَرَبَّصۡنَ﴾⟪2:228⟫؟ قيل: لما كانت العدة تحصل من الرأي بانقضاء الأيام، نوتها أو لم تنوها، أجدت أو لم تجد صار لفظ الخبر أملك له من لفظ الأمر، ويدلك على صحة هذا الاعتبار إتيان جميع العدد بلفظ الخبر وقوله: ﴿وَلَا يَحِلُّ لَهُنَّ أَن يَكۡتُمۡنَ مَا خَلَقَ ٱللَّهُ﴾⟪2:228⟫ عنى كتمان ما في أرحامهن من الحيض والحبل، وأنه لا يجوز أن تكون حاملا، فتقول: ليست بحامل، أو لم تكن حاملا، فتقول: أنا حامل، ولا أن تدعي الحيض أو تنفيه على ذلك، وذلك عام في كل ذلك، وإن مثل كل واحد من متقدمي المفسرين لشيء من ذلك، ومن قال: لا يجور أن يكون الحيض، لأن الحيض لم يخلق في الرحم، وإنما هو دم يرد إليه من جميع البدن، فعلى هذا قوله: ﴿فِيٓ أَرۡحَامِهِنَّ﴾⟪2:228⟫ لا يكون من صلة خلق، بل يكون من صلة قوله (ولا يكتمن)، أي: لا يكتمن في أرحامهن ما خلق الله فإنه لا شك أن يحصل في الرحم خلق فيه أو لم يخلق، ونهيها عن كتمان ذلك دال على أن قولها مقبول فيما تدعي من حيضها وحملها فيما يتعلق بحقها، فإن تعلق بذلك شي، ليس من حقها، فيجور أن لا يقبل إذا اتهمت، كمن يقول: \" عبدي حر \" أو \" امرأته طالق إن حاضت \"، فقالت: \" قد حضت، فمتى لم يصدقها لم يعتق عبده ولم يطلق امرأته، وقوله: ﴿إِن كُنَّ يُؤۡمِنَّ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ﴾⟪2:228⟫، فليس ذلك شرطا في أنهن إذا لم يكن مؤمنات، يجوز أن يكتمن، وإنما ذلك تنبيه أنه مناف للإيمان، وأنه ليس من فعل المؤمن، كقوله: ﴿وَلَا تَأۡخُذۡكُم بِهِمَا رَأۡفَةٞ فِي دِينِ ٱللَّهِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ﴾⟪24:2⟫، وقوله: ﴿وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَٰلِكَ﴾⟪2:228⟫ دال عي بينة مراجعتها ما دامت معتدة، ولم يعن بالرد تجديد نكاح يشارك فيه غيره في الحال، وإنما عنى الرجعة الموجبة لبقاء النكاح بلد انقضاء الحيض التي إذا لم تكن لكان يزول النكاح، وظاهر الآية أن إباحة هذه الرجعة شريطة الإصلاح، لكن لا خلاف أنه\n⟦1:469⟧\nإذا راجعهما مضارا بها، فرجعته صحيحة، فدل هدا الإجماع أن ذلك تهديد للمراجع أن لا يقصد الإضرار بها، كقوله: ﴿وَلَا تُمۡسِكُوهُنَّ ضِرَارٗا لِّتَعۡتَدُواْۚ﴾⟪2:231⟫، ثم قال: ﴿وَمَن يَفۡعَلۡ ذَٰلِكَ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ﴾⟪2:231⟫ تنبيها أن فاعل ذلك ظالم، وأن الرجعة في الحكم صحيحة، وقيل: تسمية (بعلا) دلالة أن ما دون الثالثة من الطلاق لا يرفع الزوجية، وأن الرجعة مادامت معتدة وقوله: (والمطلقات) عامة في الرجعية وغير الرجعية، (وبعولتهن) خاص في الرجعية، بدلالة التي تتلوها، وليس قول من قال هذه الآية نسخ منها حكم الحامل، ومن ليست بذات حيض بشيء فإن ذلك تخصيص لا نسخ، وإن كان قد سماه بعض القدماء نسخا وقوله: ﴿وَلَهُنَّ مِثۡلُ ٱلَّذِي عَلَيۡهِنَّ بِٱلۡمَعۡرُوفِۚ وَلِلرِّجَالِ عَلَيۡهِنَّ دَرَجَةٞۗ﴾⟪2:228⟫ يتبين أن لكل واحد على الآخر حقا كحق الآخر، فمما تشاركا فيه مراعاتهما للمعنى الذي شرع لأجله النكاح وهو طلب النسل، وتربية الولد، ومعاشرة كل واحد منهما للآخر بالمعروف وحفظ المنزل، وتدبير ما فيه وسياسة ما تحت أيديهما، حماية كل واحد على الآخر بقدر جهده وحده، وقوله: ﴿وَلِلرِّجَالِ عَلَيۡهِنَّ﴾⟪2:228⟫ هو من وجه تنبيه لفضل الرجل على المرأة بالجملة، ومن وجه كالاستثناء بأن له عليها حقا، ليس لها عليه، أما فضله عليها، فقد نبه علبه بقوله: ﴿وَلَيۡسَ ٱلذَّكَرُ كَٱلۡأُنثَىٰۖ﴾⟪3:36⟫ ودل عليه النبي- عليه السلام بقوله: \" إنكن ناقصات الدين والعقول \" فقيل: وما نقصان دينهن، فقال: إن إحداهن تقعد\n⟦1:470⟧\nنصف دهرها لا تصلي، ونقصان عقلهن أن شهادتها على النصف من شهادة الرجل، وقيل: من نقصها أن شر ما في الرجال الجبن والبخل، وهما خير ما في النساء، ولكونهن ناقصات عظم الله نسبة البنات إليه أكثر كما تعظيمه نسبة الابن، وإلا كانا منكرين، فقال تعالى: ﴿أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلۡأُنثَىٰ﴾⟪53:21⟫، وقال: ﴿وَيَجۡعَلُونَ لِلَّهِ مَا يَكۡرَهُونَۚ﴾⟪16:62⟫، وقال: وإذا بشر أحدهم بما ضرب للرحمن مثلا ظل وجهه مسودا وهو كظيم}، وقال: ﴿أَصۡطَفَى ٱلۡبَنَاتِ عَلَى ٱلۡبَنِينَ﴾⟪37:153⟫، وعظم تعالي نسبة الملائكة إلى الأنوثة، فقال: ﴿وَجَعَلُواْ ٱلۡمَلَٰٓئِكَةَ ٱلَّذِينَ هُمۡ عِبَٰدُ ٱلرَّحۡمَٰنِ إِنَٰثًاۚ﴾⟪43:19⟫.\nولكن الأنوثية نقص جعل القوه الانفعالية أنثى، والقوة الفاعلة ذكر حتى شبهوا السماء بالفحل والأرض باللقوحة، وقالوا حديد ذكر، وحديد أنثى، وقال تعالى: ﴿إِن يَدۡعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثٗا﴾⟪4:117⟫، أي أصناما مفعولة غير فاعله، وأما فضل حقوقه عليها، فقيل: عشرة أشياء جعل الطلاق إليه من دونها، وإباحة ضربها عند النشوز، أو هجران فراشها، ووجوب إجابتها إياه دعاها إلى الفراش، والائتمار له إذا نهاها عن الخروج، وأن ميراثه منها أكثر من ميراثها منه، وأنه إذا قذفها فله إسقاط الحد باللعان، وليس لها ذلك وأن له أن يجمع بينها وبين غيرها، وليس لها أن تجمع بينه وبين غيرة، وليس لها أن تصوم تطوعا ولا أن تحج فرضا إلا بإذنه، وله ذلك من دون إذنها.\nوإلى وهذه الجملة أشار بقوله: ﴿ٱلرِّجَالُ قَوَّٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعۡضَهُمۡ عَلَىٰ بَعۡضٖ﴾⟪4:34⟫ ونبه بقوله: ﴿وَٱللَّهُ عَزِيزٌ حَكِيمٌ﴾⟪2:228⟫ أنه يحكم بكل ما يشاء، فلا يغالب لعزة، ويتقن كل ما يفعله فيصيب بحكمته، وفيه وعد وإبعاد على مجازاتهما فيما يتحريانه من صلاح وفساد ..\n⟦1:471⟧"}, {"a": [229], "v": 1, "p": 471, "ev": 1, "ep": 475, "sid": 472, "t": "قوله - عز وجل -:\n﴿ٱلطَّلَٰقُ مَرَّتَانِۖ فَإِمۡسَاكُۢ بِمَعۡرُوفٍ أَوۡ تَسۡرِيحُۢ بِإِحۡسَٰنٖۗ وَلَا يَحِلُّ لَكُمۡ أَن تَأۡخُذُواْ مِمَّآ ءَاتَيۡتُمُوهُنَّ شَيۡـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِۖ فَإِنۡ خِفۡتُمۡ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيۡهِمَا فِيمَا ٱفۡتَدَتۡ بِهِۦۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَعۡتَدُوهَاۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ﴾⟪2:229⟫\nالآية (229) - سورة البقرة.\nالمرة: فعلة من مر يمر مرا، ومرورا، فعبر بها لكن الفعلة، وإمرار الحبل إرساله في الفتل حتى يمر مرا، ومر الشيء صار مرا أصله من الأول، وهو فيما لا يطيب أكله، كساع فيما يطيب، وهما للذهاب، والمر الذي يعمل به استعارة، والإمساك أصله من المسك وتصور منه إمساكا للبدن، ولما يجعل فيه بعد السلخ فقيل: (أمسكت كذا) أي ضبطته ضبط ما المسك لما فيه، وكنى بالمسك\nعن البخيل، والتسريج كالتطليق في أنه من: برحت الماشية، كما أن الطلاق من: \" أطلقت البعير، والمعروف مالا تنكره العقول الصحيحة، وسمي الجود معروفا لمعرفة العقول كلها حسنه.\nوعلى هذا قال الشاعر:\nولم أر كالمعروف أما مذاقة ...\nفحلو وأما وجهه فجميل\nوقيل: الخوف هاهنا: الظن، وقيل: اليقين، واحتج بقول الشاعر:\nولا تدفنني بالفلاة فإنني ...\nأخاف إذا مامت ألا أذوقها\n⟦1:472⟧\nوذلك نظر من المفسر إلى مقتضى الخوف، فقد يكون الخوف عن أمارة ضعيفة تقتضي الظن، وعن أمارة قوية تقتضي اليقين، فقوله: ﴿ٱلطَّلَٰقُ مَرَّتَانِۖ﴾⟪2:229⟫ ليس ذلك للجنس متناولا لكل طلاق، بل هو إشارة إلى الطلاق المتقدم ذكره الذي قال فيه:\n﴿وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ﴾⟪2:228⟫، فبين أن ذلك الطلاق الذي فيه المراجعة مرتان، وأصله الطلاق مرتين، نحو الخروج مرتين، ثم رفع كقوله: ﴿ٱلۡحَجُّ أَشۡهُرٞ مَّعۡلُومَٰتٞۚ﴾⟪2:197⟫، وبقول: ﴿أَوۡ تَسۡرِيحُۢ بِإِحۡسَٰنٖۗ﴾⟪2:229⟫ منهم من حمله على الطلقة الثالثة، وروى عن النبي - صلى الله عليه وسلم - أن بعضهم سمع الآية، فقال: فأين الثالثة؟ فقال- عليه السلام: \" التسريح بإحسان.\nومنهم من حمل ذلك على ترك الرجعة \" والصحيح أنه محمول عليها، لأنه يكون بالرجعة ممسكا لها، ويتركها حتى تنقضي عدتها، أو بتطليقها الطلقة الثالثة يكون سرحا لها، لكن لما كان اللفظ مترددا بين الأمرين بين من بعد حكمها إذا طلقها ثالثة بقوله: ﴿فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعۡدُ حَتَّىٰ تَنكِحَ زَوۡجًا غَيۡرَهُۥۗ﴾⟪2:230⟫.\nإن قيل: كيف جعل الإمساك هاهنا الرجعة؟ قيل: لأنه ضد الطلاق، وقد كان الطلاق موجبا للفرقة بعد مضي ثلاث حيض، فسمي الرجعة إمساكا لبقاء النكاح به.\nإن قيل: كيف علق التسريح بالإحسان؟ وهل بينه وبين المعروف فرق؟\nقيل: الإحسان أعم معنى من المعروف، لأن الشيء قد يكون معروفا، أي غير منكر، ولا يكون\n⟦1:473⟧\nمستحسنا، فكل إحسان معروف، وليس كل معروف إحسانا، فبين أن من حق المسرح أن يبذل ما يزيد على الإنصاف تنزها، وذلك على حسب ما كانوا يراعون في بذل مصارف المعروف لمن يرتحل عنهم، وكما بين أن له الرجعة في تطليقتين، بين بقوله: ﴿فَإِن طَلَّقَهَا﴾⟪2:230⟫ أن لا رجعة بعد الثالثة، فإن ما زاد علي الثالثة من الطلاق لا حكم له بوجه، فقد كانت العرب تطلق مرة بعد أخرى ما شاءت، وتراجع قبل انقضاء العدة، فأبطل تعالى ذلك، وفي الآية دلالة أن له أن يطلق مرتين في طهر واحد من حيث أنه لم يفصل، ودلالة أن الطلاق في الحيض يقع، وذلك قال عليه السلام- لأبن عمر لما قال: أرأيت لو طلقها ثلاثا؟ قال: \" أذن بانت منك امرأتك، عصيت ربك \"، وأجمع فقهاء الأمصار أن قوله: ﴿ٱلطَّلَٰقُ مَرَّتَانِۖ﴾⟪2:229⟫ إذا لم يكن الزوجان مملوكين، واتفقوا أن الرق يوجب نقصان الطلاق، لكن اعتبر أبو حنيفة الطلاق بالنساء، وهو قول علي والشافعي، واعتبر بالرجال، وهو قول عثمان وزيد، وإليه ذهب مالك، وقوله: ﴿وَلَا يَحِلُّ لَكُمۡ أَن تَأۡخُذُواْ مِمَّآ ءَاتَيۡتُمُوهُنَّ شَيۡـًٔا﴾⟪2:229⟫ فلا خلاف أنها إذا سمحت بشيء من مهرها للزوج فسائغ، لقوله: ﴿فَإِن طِبۡنَ لَكُمۡ عَن شَيۡءٖ مِّنۡهُ نَفۡسٗا فَكُلُوهُ﴾⟪4:4⟫، فأما إذا كان على وجه الخلع، فلا يجوز إلا على وجه دون وجه، واختلفوا متى يجوز مخالعتها؟ وكم قدر المال الذي به يجوز؟، وعند من يجوز؟\nفذهب بعضهم إلى أنه يكره الخلع مع سلامة الحال، لأن الطلاق مكروه إذا توفرت المرأة على ما يلزم من حكم الزوجية لقوله- عليه السلام: \" أبغض الحلال إلي الله الطلاق \" هذا مع إمكان المراجعة والخلع الذي ترتفع المراجعة معه أولى بأن يكره، وإن خافا ألا يقيما حدود الله جاز بلا خلاف لظاهر الآية، وإن خافت ولم يخف الزوج، فيجوز إلا عند أهل الظاهر، وعلى ذلك دل شأن امرأة\n⟦1:474⟧\nثابت بن قيس لما كرهت الزوج، فأمرها- عليه السلام- أن ترد إلي حذيقة ما كان قد مهرها، وقال الحسن: لا يجوز حتى تقول المرأة: لا أغتسل عنك، ولا أقربك، ونحو ذلك ...\nوقال إبراهيم: \" لا يجوز حتى تعصيه ولا تبر يمينه وإن خاف هو ولم يخف ولم يرها على فاحشه \"، لا يحل له أخذ شيء منها بالمخالعة لقوله- عز وجل:\n﴿وَإِنۡ أَرَدتُّمُ ٱسۡتِبۡدَالَ زَوۡجٖ مَّكَانَ زَوۡجٖ وَءَاتَيۡتُمۡ إِحۡدَىٰهُنَّ قِنطَارٗا فَلَا تَأۡخُذُواْ مِنۡهُ شَيۡـًٔاۚ﴾⟪4:20⟫ الآية.\nوذلك في الحكم سائغ وإن كان منهيا عنه، وعند مالك يرد إليها مالها، وقال الأوزاعي؟: \" إذا خالع امرأته وهي مريضة، فإن ما تبدله في ثلثها إن كانت ناشزة، وإن لم يكن ناشزة رد عليها، وكان له عليها الرجعة، فأما القدر الذي يخالع عليه \" فمنهم من قال: لا يجوز إلا بأقل من الهر المسمي لقوله تعالى: ﴿وَلَا يَحِلُّ لَكُمۡ أَن تَأۡخُذُواْ مِمَّآ ءَاتَيۡتُمُوهُنَّ شَيۡـًٔا﴾⟪2:229⟫، وذلك يقتضي التبعيض، وقال علي والحسن وابن المسيب وطاوس وابن جبير: لا يجوز بأكثر مما أعطاها لما روي أن رجلا خاصم امرأته إلى النبي- عليه السلام، فقال: تردي إليه ما أخذت منه؟ قالت: نعم وزيادة، فقال عليه السلام: أما الزيادة فلا ..\n، ومنهم من أجاز بأكثر من ذلك، وهو الأظهر، وأما عند من يجور، فإن الحسن وابن سيرين قالا: لا يجوز إلا عند السلطان، وقال فقهاء الأمصار: يجوز، لأن ظاهر الآية لم يعرف، ومن قرأ (تخافا)، فخطاب لهما، لأنهما أعرف بأحوالهما من غيرهما هل يقيمان أو لا يقيمان؟\nفإذا قرئ (تخافا) (3) على ما لم يسم فاعله، فالخطاب للحاكم، والمفتي بأن لا يحل أن يحكم للزوج\n⟦1:475⟧\nبالأخذ إلا إذا عرفوا ذلك منهما، والقراءة الأولى أجود، لأن هذا المعنى استفيد من قوله: ﴿فَإِنۡ خِفۡتُمۡ﴾⟪2:229⟫ ..\nإن قيل: لم رفع الجناح عنهما وذلك يجب أن يرفع عن الزوج الذي يأخده؟ قيل: لأن من الدفع ما يؤثم الأخذ والدافع كالربا، ومنه ما يؤثم أحدهما، فبين أن الجناح مرفوع عنهما، وليس ما قال الفراء أنه لا جناح على أحدهما، فنسب إليهما، كقوله تعالى: ﴿يَخۡرُجُ مِنۡهُمَا ٱللُّؤۡلُؤُ﴾⟪55:22⟫ بشيء، وذكر أن كل ما بينه حدود الله، ولا يجوز تعديها، فإن من تعداها ظالم يستحق ما يستحقه .."}, {"a": [230], "v": 1, "p": 475, "ev": 1, "ep": 476, "sid": 476, "t": "قوله- عز وجل:\n﴿فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعۡدُ حَتَّىٰ تَنكِحَ زَوۡجًا غَيۡرَهُۥۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِۗ وَتِلۡكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوۡمٖ يَعۡلَمُونَ﴾⟪2:230⟫\nالآية (230) - سورة البقرة.\nهذا الحكم متعلق بقوله: ﴿ٱلطَّلَٰقُ مَرَّتَانِۖ﴾⟪2:229⟫، وقدم فصل بينهما بحكم الخلع وكيفية جوازه، فلما فرغ منه رجع إلى حكم الطلاق، فقال: ﴿فَإِن طَلَّقَهَا﴾⟪2:230⟫ أي بعد الثنتين فلا تحل له أو لا يجوز أن يتزوج بها حتى تنكح زوجا غيره، وبين أن ليس للإنسان أكثر من ثلاث تطليقات، والنكاح الذي يحلها للزوج الأول ظاهره يقتضي العقد، وإليه ذهب سعيد بن المسيب وأهل الظاهر، لكن قد ورد عن النبي -عليه السلام- ما اقتضي معه الوطء حيث قال: \" حتى تذوقي عسيلته، ويذوق عسيلتك \"، وقيل: حكمة الله\n- عز وجل- في تحريمها عليه إلا بعد أن يتزوج زوجة أخر الردع إلى التسرع في الطلاق، ولهذا دعا أن يتأنى في تطبيقها، فيطلقها للعدة طلقة بعد طلقة، ونبه على ذلك بقوله: ﴿لَا تَدۡرِي لَعَلَّ ٱللَّهَ يُحۡدِثُ بَعۡدَ ذَٰلِكَ أَمۡرٗا﴾⟪65:1⟫.\n⟦1:476⟧\nثم قال: ﴿فَإِن طَلَّقَهَا﴾⟪2:230⟫ يعني الزوج الثاني، ﴿فَلَا جُنَاحَ عَلَيۡهِمَآ﴾⟪2:230⟫، أي لا جناح أن يتزوج بها على شرط أن يظن أن يقيم حدود الله، وعلق بالظن، لأن ما يكون من الإنسان في المستقبل من الممكنات لا سبيل إلى معرفته إلا بالظن، وليس شرطا في صحة النكاح، بل في إباحته ورفع المآثم، لأن العقد صحيح، فإن ظنا أن لا يقيما حدود الله، وبين أن تلك الحدود بينها لقوم يعلمون- تنبيها أنهم هم الذين يتبينونها، لقوله: ﴿إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكۡرَ﴾⟪36:11⟫."}, {"a": [231], "v": 1, "p": 476, "ev": 1, "ep": 478, "sid": 477, "t": "قوله - عز وجل -:\n﴿وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ سَرِّحُوهُنَّ بِمَعۡرُوفٖۚ وَلَا تُمۡسِكُوهُنَّ ضِرَارٗا لِّتَعۡتَدُواْۚ وَمَن يَفۡعَلۡ ذَٰلِكَ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ وَلَا تَتَّخِذُوٓاْ ءَايَٰتِ ٱللَّهِ هُزُوٗاۚ وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ وَمَآ أَنزَلَ عَلَيۡكُم مِّنَ ٱلۡكِتَٰبِ وَٱلۡحِكۡمَةِ يَعِظُكُم بِهِۦۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٞ﴾⟪2:231⟫\nالآية (213) - سورة البقرة.\nهذه الآية ظاهرها إعادة حكم ما تقدم، وأنه يجوز مراجعتها بعد انقضاء العدة، وقد فسرت تفسيرين، أحدهما أن الأولى حكم بجواز الرجعة بعد التطليقة والتطليقتين، وتحريم الرجعة بعد الثالثة، وهذه تقتضي جواز رجعتها ما دامت في العده لا عن الطلاق الثالث، وفيه زيادة حكم وإن كانت تقتضي بعض ما أفادت الأولى، وهي ذكر معها من الأحكام، وقوله: ﴿فَبَلَغۡنَ أَجَلَهُنَّ﴾⟪2:231⟫، مشكل ، لأن المراجعة ثابتة قبل انقضاء العدة، وظاهر هدا يقتضي أن المراجعة بعد انقضاء العدة، ووجه ذلك أن الأجل هاهنا زمان العدة لإتمام العدة، وأيضا، فإنه يقال إدا فعلت كذا ويعني إذا خصت لا إذا فرغت منه، نحو: ﴿وَإِذَا قُلۡتُمۡ فَٱعۡدِلُواْ﴾⟪6:152⟫، فقوله: فبلغن أي: حضن في زمان بلوغ الأجل، وأيضا فقولهم: (بلغ) يقال لما شارف وإن لم ينته، فيقول: إذا طلبتم وشارفن الأجل، فأمسكوهن،\nإن قيل: ولم خص المشارفة، وقيل المشارفة هذا حكمه، قيل: لما كانوا يطلقون المرأة فيتركونها حتى تشارف، انقضاء\n⟦1:477⟧\nالعدة، ثم يراجعونها إضرارا بها، خص ذلك بالذكر، والثاني من التفسيرين أن الآية فيمن طلق امرأته تطليقة، وتركها حتى تنقضي عدتها، ثم يريد التزوج بها، وزاد أنه ذكر فيما قبل حكم الخلع، وحكم ما تصح مراجعته، وما لا تصح، وما يحتاج أن يتعاطاه المراجع، وذكر في هذه الآية حكم المطلقة تطليقة وقد انقضت عدتها، فقال: إذا طلقتم تطليقه، ﴿فَبَلَغۡنَ أَجَلَهُنَّ﴾⟪2:231⟫، أي انقضت عدتها، فأمسكوهن أي تزوجوا بهن على حكم الله أو اتركوهن على حكمه ..\nإن قيل: كيف يصح أن يعبر لكن التزويج بالإمساك؟ قيل: إنما استعمل الإمساك في هذا للتزوج، لأنه كان بعد أن كانت تحته، وقبل أن يملكها غيره، فقال: ﴿فَأَمۡسِكُوهُنَّ﴾⟪2:231⟫ تنبيها على هذا المعنى، أو ﴿سَرِّحُوهُنَّ﴾⟪2:231⟫، أي أفرجوا عنها، ولا تخطبوها، قال: والذي يدل على هذه الآية التي بعدهما، فإنها نزلت فيمن خطب امرأة كان قد طلقها تطليقها، فانقضت عدتها، فمنعت إياه، فأوصى تعالى الخاطب في هذه أنه إن أراد أن يمسمكها بإعادة نكاحها، فليستعمل المعروف، وإلا فليحلها، وجل المفيرين على المعنى الأول،\nإن قيل: لم علق التسريح هاهنا بمعروف وفي الأول بإحسان؟ قيل: إنه لا أعيد ذكر الرجعة علق التسريح بالمعروف تنبيها أنه إن لم تراعوا في تسريحها الإحسان، فراعوا فيه المعروف، كما قال بعض الناس لسلطان: \" إن لم تحسن فعلا \"، وقوله: ﴿وَلَا تَتَّخِذُوٓاْ ءَايَٰتِ ٱللَّهِ﴾⟪2:231⟫ قيل: معناه: لا تهزوا بها، ولا تحسبوها عبثا، نحو: ﴿وَمَا خَلَقۡنَا ٱلسَّمَآءَ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا لَٰعِبِينَ﴾⟪21:16⟫، وقيل: معناه: لا تعملوا بخلافها، فتكونوا كالهازئين بها، وقال أبو الدرداء: \" كان في أول الإسلام يطلقون ويعتقون، ثم يقولون: كنا نلعب \"، والإشارة بالآية إليه، وقال عليه السلام- \" ثلاث جدهن جد، وهزلهن جد النكاح، والطلاق، والعتاق \" وحث على معرفة نعمه وما أنعم عليهم بالكتاب والحكمة ..\nإن قيل: كيف أفرد الكتاب والحكمة عن النعمة وهي أفضل النعم وأجلها؟ قيل: لأمرين، أحدهما: أن النعمة في تعارف الخاصة والعامة هي كثرة في المال، وصحة في البدن وسائر الزين الدنيوية، ولا يعرف الكتاب والحكمة نعمه إلا أولوا الألباب، والثاني: أفردهما التخصيص والتفصيل كإفراد جبريل وميكائيل عن الملائكة.\n⟦1:478⟧"}, {"a": [232], "v": 1, "p": 478, "ev": 1, "ep": 480, "sid": 479, "t": "قوله - عز وجل -:\n﴿وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَلَا تَعۡضُلُوهُنَّ أَن يَنكِحۡنَ أَزۡوَٰجَهُنَّ إِذَا تَرَٰضَوۡاْ بَيۡنَهُم بِٱلۡمَعۡرُوفِۗ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمۡ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۗ ذَٰلِكُمۡ أَزۡكَىٰ لَكُمۡ وَأَطۡهَرُۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ﴾⟪2:232⟫\nالآية (232) - سورة البقرة.\nالعضل المنع مع.\nتضييق، يقال: عضلت الدجاجة بيضها، والمرأة بولدها، وعلى طريق الاستعارة قال:\nترى الأرض منا بالفضاء مريضة ...\nمعضلة منا بجمع عرمرم\nومنه: داء عضال،\nوالعضلة الدامية، والعضلة لحم مكتنز في عصب، وبلوغ الأجل هاهنا لاستيفاء العدة ولما بين تعالى بالآيات المتقدمة ما يجب على كل واحد من الزوجين لصاحبه في النكاح، وعند المراجعة والفدية والفراق والطلاق عدل إلى بيان ما يلزم الولي، وما يحرم عليه في تزويجها وإنكاحها، وقيل: ﴿فَلَا تَعۡضُلُوهُنَّ﴾⟪2:232⟫ خطاب للأختين، وعضلها أن يراجعها إضرارا بها، والصحيح أنه خطاب للأولياء، بدلالة ما روي: أن الآية نزلت في معقل بن يسار وكانت أخته تحب ابن عم له، فطلقها طلقة فلما انقضت عدتها خطبها، وهي تريد أن ترجع إليه، فقال معقل: والله لا أزوجها أبدا، فأنزل الله تعالى هذه الآية فدعاه النبي- عليه السلام، فتلاها عليها فقال: \" سمعا لربي وطاعة \" والحكم الوارد في سبب\n⟦1:479⟧\nلا يصح أن يكون السب خارجا عنه وإن أريد معه غيره، واختلف في هدا العضل، فعند الشافعي لما كان نكاح امرأة بكرا كانت أو ثيبا لا يصح إلا بالولي، صار في منعها عن أكفائها، وعند أبي حنيفة لما كان يصح للثيب أن تتزوج بنفسها، صار في الاعتراض علتها في سبب المهر والكفاءة، قال: والآية تدل أن لها التزوج بنفسها، لأنه قال: ﴿أَن يَنكِحۡنَ﴾⟪2:232⟫ فنسب النكاح إليهن، وقال أصحاب الشافعي: إنما نسب إليها، لأنه لا يصح إلا برضاها، وكل من لا يتم الفعل من دونه، يصح أن ينسب ذلك الفعل إليه،\nوأما المعروف المتراضي به في قوله تعالي: ﴿إِذَا تَرَٰضَوۡاْ بَيۡنَهُم بِٱلۡمَعۡرُوفِۗ﴾⟪2:232⟫ فعام في كل ما يرجع إلى العقد، لقدر الهر وما يظهر من الرعية وخلافها، وما يعاون الزوجية مما صححها، وفي كل ما يرجع إلي حقوق الزوجية، فألزم الولي أن لا يعضلها إذا تراضوا بما هو معروف، وقوله تعالى: ﴿ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمۡ يُؤۡمِنُ بِٱللَّهِ﴾⟪2:232⟫ فخص المؤمنين بالوعظ، وهو أنه يريد حصول الاتعاظ، وليس ذلك إلا للمؤمنين، وقوله: ﴿ذَٰلِكُمۡ أَزۡكَىٰ لَكُمۡ وَأَطۡهَرُۚ﴾⟪2:232⟫ زكاة الإنسان وطهارته في حقيقة كونه بحيث يستحق في الدنيا الأوصاف المحمودة، وفي الآخرة عظيم المثوبة، وأن يصلح في الآخرة لمجاورة الله الأعلى بل مجاورة الله- عز وجل - ولهذا قال: ﴿قَدۡ أَفۡلَحَ مَن تَزَكَّىٰ﴾⟪87:14⟫، وقال: ﴿قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا﴾⟪91:9⟫، وجعل تعالى الدلالة على أن ذلك أزكى وأطهر أنه قد حكم بذلك وهو عالم بالأشياء كلها وأنتم غير عالمين بها، فإذا علم وحكم فحق عليكم أن تقبلوا منه حكمه،\nإن قيل: لم قال: ﴿ذَٰلِكَ يُوعَظُ بِهِۦ﴾⟪2:232⟫ ثم قال: ﴿ذَٰلِكُمۡ أَزۡكَىٰ﴾⟪2:232⟫؟\nقيل: في ذلك أجوبة ..\nأحدها:\nأن كاف الخطاب مع (ذا) تارة تفيد الخطاب، فيراعى فيه المخاطبون فيثني، ويجمع، ويؤنث بحسبهم، وتارة يعتبر به الفرق بين القريب والبعيد، فليقال: (ذا) لما يتصور قريبا، و (ذاك) لما يتصور بعيدا، فلا يثنى ولا يجمع، فعلى هذا؟ (ذلك)، و (ذلكم).\n⟦1:480⟧\nوالثاني أن الكاف الأولى خطاب للنبي- عليه السلام، والثانية للكافة، وعلى هذا قوله: ﴿يَٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ﴾⟪65:1⟫ وفائدة ذلك أن قوله: (ذلك) إشارة إلى حقائق ما تقدم، ولا يكاد يتصوره إلا هو- عليه السلام-، ومن يدانيه من أولياء الله عز وجل-، وذلك إشارة إلى العمل، والعمل به يتشارك فيه كافة المسلمين، والثالث: أن خطاب الجمع تارة يعتبر بلفظ مفرد، فيفرد خطابهم نحو بهذا القبيل: \" فعلت كذا \"، وتارة يعتبر معنى الجمع، فيقال: فعلتم فعلى هذا، لو قيل في الأول: (ذلكم)، وفي الثاني (ذلك) لصح، أو قيلا بلفظ واحد لصح."}, {"a": [233], "v": 1, "p": 480, "ev": 1, "ep": 484, "sid": 481, "t": "قوله - عز وجل -:\n﴿وَٱلۡوَٰلِدَٰتُ يُرۡضِعۡنَ أَوۡلَٰدَهُنَّ حَوۡلَيۡنِ كَامِلَيۡنِۖ لِمَنۡ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَۚ وَعَلَى ٱلۡمَوۡلُودِ لَهُۥ رِزۡقُهُنَّ وَكِسۡوَتُهُنَّ بِٱلۡمَعۡرُوفِۚ لَا تُكَلَّفُ نَفۡسٌ إِلَّا وُسۡعَهَاۚ لَا تُضَآرَّ وَٰلِدَةُۢ بِوَلَدِهَا وَلَا مَوۡلُودٞ لَّهُۥ بِوَلَدِهِۦۚ وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَٰلِكَۗ فَإِنۡ أَرَادَا فِصَالًا عَن تَرَاضٖ مِّنۡهُمَا وَتَشَاوُرٖ فَلَا جُنَاحَ عَلَيۡهِمَاۗ وَإِنۡ أَرَدتُّمۡ أَن تَسۡتَرۡضِعُوٓاْ أَوۡلَٰدَكُمۡ فَلَا جُنَاحَ عَلَيۡكُمۡ إِذَا سَلَّمۡتُم مَّآ ءَاتَيۡتُم بِٱلۡمَعۡرُوفِۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ﴾⟪2:233⟫\nالآية (233) - سورة البقرة.\nالرضاع أصل، وعنه استعير \" لئيم راضع \" لمن تنامي لؤمه وإن كان ذلك في الأصل ممن كان يرضع غنمه، لئلا يسمع صوت شخبة، لكن تعورف في اللؤم، حتى قيل: \" رضع فلان أي لؤم \"، وسمي الثنيتان الراضعتين، لاستعانة الصبي بهما في الرضع، (وكسوتهن) عن الكسوة استعير: اكتست الأرض بالنبات، وكسوته ثناء أو هجاء، وصار الكساء لضرب مخصوص من الثبات.\nوالتكليف أصله فيما جعلت به الإنسان كلفا، وصار في التعارف لما ألزمته وأكلفته بكذا جعلته كلفا به، والكلف بالوجه لتصوره كلفه به، والميراث أصله فيما أصبته من غيره حيا كان الموروث منه أو ميتا، لكن صار في التعارف اسما لا يخلفه الميت من المال، والفصل ضد الوصل كالفضل، واستعماله في قطع الرطب من النبات، ومنه الفضيل، يقال: فصلت بين الكلام والعقد، وفي القضاء، وسمي الفطام فصالا للفصل\n⟦1:481⟧\nبين غذائي الصبي، وتعورف الفصل في السقب والتشاور لاستخراج الرأي من الغير، من شرت العسل، (وشورت الفرس) استخرجت جربه وأشرت إليه بكذا، أي أخرجته بالإيماء من بين ما يشاكله، وسمي الإصبع مشيرة، لكونها ذات إشارة كما سميت مسبحة وسبابه، وسميت السنة حولأ، لانقلابها في فصولها وشهورها، ودوران الشمس في مطالعها ومغاديها، وذكر جماعة من الفقهاء أن قوله: ﴿وَٱلۡوَٰلِدَٰتُ يُرۡضِعۡنَ﴾⟪2:233⟫ أمر وإن كان لفظه خبرا ، لأنه لو كان خبرا لم يقع مخبره بخلافه، وهذه قضية إنما تصح في كل خبر لفظه لا يحتمل التخصيص، فأما إذا كان عاما يمكن أن يخصص على وجه يخرج من كونه كذبا، فادعاء ذلك فيه ليس بواجب، وهذه الآية مما يمكن ذلك فيه، ثم ذلك لو كان أمرا لكان أمرا للوالدات، وقد علم أن الأم وإن لم تكن مكلفة فهي أحق برضاعها،\nفإن قيل: فإذا لم يكن أمرا فما وجهه؟\nقيل أخبر الله تعالى أن حكم الله في ذلك أن الوالدات أحق بإرضاع أولادهن سواء كانت في حبالة الزوج أو لم تكن، فإن الإرضاع من خصائص الولادة، لا من خصائص الزوجية، ولهذا قال عليه السلام: في الأمر إنها أحق بالولد ما لم تتزوج، وإنما ذكر (كاملين) لأنه قد يقال: \" فلان فعل كذا سنتين \" وإن كان ذلك في سنة وبعض الأخرى، وكذا يقال: شهرين ويومين، فأريد إزالة هذه الشبهة، وقال الفقهاء: لما جعل الرضاع حولين وقال في موضع: ﴿وَحَمۡلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهۡرًاۚ﴾⟪46:15⟫، نبه على أن الولد قد يولد لستة أشهر، وفيه تنبيه على لطيفة، وهو أن الولد متى كان زمان حمله وفاصله أقل ثلاثين شهرا أضر ذلك به، فإذا ولد لسبعة أشهر لم يضره أن ينقص رضاعه عن الحولين، وجعل ابن عباس ذلك حكما شرعيا، وقال: يجب أن يكون الحمل والرضاع هذا القدر، وقوله تعالى: ﴿لِمَنۡ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَۚ﴾⟪2:233⟫ أي هذا التوقيت ليس بفرض، لكن لمن أراد إتمام الرضاعة، وفيه تنبيه أنه لا\nيجوز تجاوز ذلك وأن لا حكم للرضاع بعد الحولين ويقويه ما روي جابر أنه قال عليه السلام:\n⟦1:482⟧\n\" لا رضاع بعد المولين \" وعلى هذا يحمل قوله: \" الرضاعة من المجاعة \" ويؤكده أن كل حكم في الشرع علق بعدد مخصوص يجوز الإخلال به في أحد الطرفين لم يجز الإخلال به في الطرف الآخر، كخيار الثلث وعدد حجارة الاستنجاء، والمسح على الخفين يوما وليلة أو ثلاثة أيام، فلما كان الرضاع يجوز الإخلال به في أحد الطرفين، وهو النقصان لم تجز مجاوزته ، وقوله: ﴿وَعَلَى ٱلۡمَوۡلُودِ لَهُۥ﴾⟪2:233⟫، أي الأب، وفائدة تخصيصه بهذا الوصف دون لفظ الأب تنبيه أن الابن في الحكم للأب، وأن حظ الأم فيه يقل وعلى ذلك دل الشاعر:\nوإنما أمهات الناس أوعية ...\nمستودعات وللأحساب أباء\nوبين تعالى أن رزق المرأة المرضعة، أي طعامها وكسوتها على الأب إذا أرضعته زوجة كانت أو مطلقة، وفيه تنبيه أن سائر نفقة الولد، على الأب لكن أجمعو أن الولد إذا كان له كفاية، فللأب أن لا ينفق عليه، وقوله: بالمعروف تنبيه، على أن النفقة بقدر اليسار والإعسار، وجعل ذلك مؤولا إليهم وإلى الحكام، ولم نجد فيه حدا لاختلاف الناس بقدر الأزمنة والأمكنة والسن وأكد ذلك بقوله: ﴿لَا تُكَلَّفُ نَفۡسٌ إِلَّا وُسۡعَهَاۚ﴾⟪2:233⟫ فلم يسم الفاعل، وقال في أخرى: ﴿لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا مَآ ءَاتَىٰهَاۚ﴾⟪65:7⟫ قيل: هذا التكليف فيه مدخل للحكام، ولغيرهم فجعل لفظه منهما في موضع، ومعناه لا يجوز تكليفه إلا وسعه، وقوله: ﴿لَا تُضَآرَّ﴾⟪2:233⟫ حمل على الجبر، وعلى الأمر، فأما إذا حمل على الجبر فهو تنبيه على ما بني\n⟦1:483⟧\nتعالى عليه الغرائز في محبة الأبوين للولد وميلهما إليه وإيثارهما له على أنفسهما، وليس ذلك في الإنسان فقط، بل في عامة الحيوانات، وذلك متقرر في النفوس حتى زعم الناس أن الهرة تأكل ولدها محبة لهم، فأخبر تعالى عما بني الطباع عليه تنبيها لكل واحد من الأبوين أن لا يتهم الأخر في ولده إذ قد يبلغ من شغف كل واحد منهما أن لا يأمن الأخر عليه وعدم نفقة الأم لفرط شفقتها على شفقة الأب، وذلك بالعلات ظاهر ثم باعتبار حال الحيوان يظهر ذلك ظهورا بينا وذلك أن الحيوانات المتوالدات على ضربين، ضرب يجتمع الأبوان على تفقد الولد وضرب تنفرد الأم به دون الأب، فالأم لا تنفك من تفقد الولد في جميع ذلك، فدل ذلك أن الله ركز في نفوس الأمهات من الإشفاق أكثر مما ركز في الآباء، وقوله: ﴿وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَٰلِكَۗ﴾⟪2:233⟫ على هذا التقدير معناه عليهم أن يجروا مجراهم، وذاك أنه لا عرف من غرائز الأقارب التحاسد بخلاف ما بين الأبوين والأولاد، حتى قيل: إن الأقارب كالعقارب، بل أضر من العقارب، نبه أن حق الأقارب أن يجروا مجراهم في شفقة البعض على البعض، إذ بينهم من النسائك، والنماذج قريب مما بين الوالدين والولد، وأما إذا حمل على الأمر، فنهى أن يفعل كل واحد من الأبوين ما يؤدي إلى مضرة الولد يكايد صاحبه، أو يضرب من النظر الفاسد، فمن المفسرين من حمل ذلك على ما تقدم ذكره، وأن الوالدة منهية عن المضارة المتعلقة بالرضاع، والمولود له منهي عن المضارة فيما يلزمه من النفقة والكسوة، ومنهم من جعل ذلك عاما في كل ما يعود بضرر على الولد من تربيته وتأديبه وتهذيبه وغير ذلك مما يكثر حصره، وقوله: ﴿وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَٰلِكَۗ﴾⟪2:233⟫ منهم من حمل ذلك على وجوب إزالة المضارة ومنهم من حمل عليه وعلى وجوب النفقة، واللفظ محتمل لها.\nوقوله: ﴿فَإِنۡ أَرَادَا فِصَالًا﴾⟪2:233⟫ أي فطاما قبل الحولين وقيل: عنى بالفصال المفاصلة عن الوالدة أو الوالد إذا تراضيا بذلك وسلمه أحدهما إلى صاحبه، وعلق ذلك بالتراضي منهما والتشاور لئلا يقدم أحدهما عن غيرة إلى ما يضر بالولد، ونبه بذلك أن كل أمر مبهم العاقبة، فالوجه فيه الإقدام عليه بعد إجماع الآراء والاستشارة، وقوله: ﴿وَإِنۡ أَرَدتُّمۡ أَن تَسۡتَرۡضِعُوٓاْ أَوۡلَٰدَكُمۡ﴾⟪2:233⟫، أي إذا امتنعت الأم أو\n⟦1:484⟧\nتزوجت، فلا جناح عليكم في استرضاع غيرها، ﴿إِذَا سَلَّمۡتُم مَّآ ءَاتَيۡتُم بِٱلۡمَعۡرُوفِۗ﴾⟪2:233⟫، أي سلمتم إلى المطلقة حقها، وقيل: إذا أتيتم المسترضعة أجرتها، وإذا قريء (ما أتيتم) بالقصر، فمعناه: إذا سلمتم ما تعاقدتم عليه، وفيه دلالة على جواز الاستئجار على الرضاع، وعلى جواز عقد الإجازة جملة وختم الآية بالحث على تقواه، وتصور علم الله لله عز وجل بكل ما آتاه الإنسان وتحراه، ومن قرأ (لا تضار) بضم الراء، فلفظ مشتبه الآية يصلح الأمر على تقدير: (لا يضارر) ولكن أدغم، فضم الراء لالتقاء الساكنين، ويصلح أن يكون على تقدير (لا يضارر) على الإخبار، وأن يكون على تقديره \" لا يضارر \" على ما لم يسم فاعله، ماذا قرئ بفتح الراء، فليس إلا النهي على تقدير (لا يضارر) وإن كان لفظه محتملا أن يكون نهيا عن مضارة الأم، كقولك: \" لا يضرر زيد \" .."}, {"a": [234], "v": 1, "p": 484, "ev": 1, "ep": 487, "sid": 485, "t": "قوله - عز وجل:\n﴿وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ أَرۡبَعَةَ أَشۡهُرٖ وَعَشۡرٗاۖ فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ بِٱلۡمَعۡرُوفِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ﴾⟪2:234⟫\nالآية (234) - سورة البقرة.\nهذه الآية ناسخة لقوله تعالى: ﴿وَصِيَّةٗ لِّأَزۡوَٰجِهِم مَّتَٰعًا إِلَى ٱلۡحَوۡلِ غَيۡرَ إِخۡرَاجٖۚ﴾⟪2:240⟫ وإن كانت\n⟦1:485⟧\nمقدمة عليه في التلاوة وظاهر الآية يقتضي تسوية الحكم في الحرة والأمة، كما قال الأصم، لكن السلف فرقوا بينهما ويقتضي أن لا فرق بين المسلمة والذمية كما قال الشافعي دون أبي حنيفة، وهذا الحكم فيمن لا تكون ذات حمل متفق عليه، فأما في ذات الحمل، فقد قال عمار وابنه عبد الله وزيد: إن عدتها أن تضع حملها وقال الحسن، هي أن تضع حملها، وتطهر من نفاسها، وقال علي: عدتها أقصى الأجلين من وضع الحمل، ومضى الشهور.\nوقد روت أم سلمة أن سبيعة بنت الحارث ولدت بعد وفاة زوجها بأربعين ليلة، فأمرها رسول الله - صلى الله عليه وسلم - الله بأن تتزوج، واختلف في الوقت الذي يعتد به من العدة، فقال ابن مسعود وابن عباس وابن عمر \" تعتد به من يوم يموت \"، وعلي والحسن: \" من يوم يأتيها الخبر \"، وقال الشعبي: إذا قامت البينة على موته فالعدة من يوم يموت، وإلا فمن يوم يأتيها الخبر والصحيح أنه يعتبر من يوم الوفاة فيه وقع الفرقة، كعدة المطلقة وكاستحقاقها الميراث من يوم الوفاة\nإن قيل: ما وجه تخصيص عدة المتوفاة بهذه المدة؟ قيل: قد ذكر الأطباء أن الولد في الأكثر إذا كان ذكرا يتحرك بعد ثلاثة أشهر وإذا كان أنثى فبعد أربعة أشهر، فجعل ذلك عدتها، وزيد عشرة استظهارا وتخصيص العشرة بالزيادة لكونها أكمل الأعداد وأشرفها لما تقدم في قوله تعالى:\n⟦1:486⟧\n﴿تِلۡكَ عَشَرَةٞ كَامِلَةٞۗ﴾⟪2:196⟫، وقوله: (والذين) هو مبتدأ، وفي خبره إشكال، فإن قوله: (يتربصن) إخبار عن الأزواج لا عن الذين وليس فيه ضمير يرجع إلى المبتدأ وقد ذكر في ذلك أربعة أجوبة ..\nالأول: تقديره: يتربصن بعدهما، وذلك عن المبرد والثاني أن الضمير في: (يذرون أزواجا) أي أزواجهم، ويتربصن عاد إلى الأزواج، والضمير إذا عاد إلى المضاف إليه كان في حكم ما عاد إلى المضاف، وذلك مثل قولهم:\n(من مات وحلف يتبين الثلثين)، وذلك عن الزجاج وعلى هذا يجب أن يجوز: (صاحب الدار انهدمت)، والثالث: عدل عن الإخبار عن الأزواج، لأن المعنى عليه، والفائدة فيه والقصد إليه، وذلك عن الكسائي والفراء وأنشد في ذلك:\nلعلي إن مالت بي الريح ملية\n....\nعلى ابن أبي دبان أن يتندما\nفسكت عن ذكر خبر لعل، والرابع: تقديره: ﴿وَيَذَرُونَ أَزۡوَٰجٗا يَتَرَبَّصۡنَ﴾⟪2:234⟫ فيكون أزواجهم مبتدأ -، ثانيا: (ويتربصن) خبره، لكن حذف المبتدأ الثاني إيجازا لا لم يشتبه المعنى، وإنما قال عشرا ولم يقل عشرة لتغليب التأنيث التذكير في باب التاريخ، وقال بعض النحويين: إن باب التأنيث غلب في باب العدد على عكس ما عليه حكم الباب، وعلى ذلك\n\" فطافت ثلاثا بين يوم وليلة\n⟦1:487⟧"}, {"a": [235], "v": 1, "p": 487, "ev": 1, "ep": 489, "sid": 488, "t": "قوله - عز وجل:\n﴿وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا عَرَّضۡتُم بِهِۦ مِنۡ خِطۡبَةِ ٱلنِّسَآءِ أَوۡ أَكۡنَنتُمۡ فِيٓ أَنفُسِكُمۡۚ عَلِمَ ٱللَّهُ أَنَّكُمۡ سَتَذۡكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُواْ قَوۡلٗا مَّعۡرُوفٗاۚ وَلَا تَعۡزِمُواْ عُقۡدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبۡلُغَ ٱلۡكِتَٰبُ أَجَلَهُۥۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِيٓ أَنفُسِكُمۡ فَٱحۡذَرُوهُۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ﴾⟪2:235⟫\nالآية (235) - سورة البقرة.\nالخطبة والخطبة كلاهما من المخاطبة، إلا أن بالضم خص لموعظة، وبالكسر لطلب المرأة، وإن كان في الأصل اسما للحالة التي عليها الخاطب، والخطب: الأمر العظيم الذي يكثر فيه التخاطب، والكن جعل الشيء في الكن، والأكنان مثله ولكن خص الأكنان بما تكنه الصدور، والكن ما يكنه البيت والثوب ونحوهما، وسميت المتزوجة كالمحصنة كنة، والكنانة جعبة غير مشقوقة تكن سهامها، والسر مما لم تشيعه مما في نفسك واعتبر تارة مما يستنكف من إظهاره، فسمي غشيان المرأة به، والاعتبار بذلك.\nقال الشاعر:\nوالستردون الفاحشات ولا\n....\nتلقاك دون الخير من ستر\nوتارة اعتبر بصيانته، فسمى المصون سرا حتى قيل:\nفلان في سر قومه، والعقد يقال في الحبل وفي العهد واليمين والسميط والرمل المتداخل، و \" ناقة عاقد \" عقدت على رحمها بمنع الفحل عن نفسها والتعريض كالكناية إلا أن التعريض أن تذكر ما يستفهم المقصود من عرضه وليس بموضوع للمفهوم عنه لا أصلا ولا نقلا، والكناية: العدول عن لفظ إلى لفظ هو بخلف الأول ويقوم مقامه، ولهذا سمي الأسماء المضمرة في النحو الكنايات، والخوالف، والتعريض المفسح فيه هاهنا كل لفظ وإشارة تدل على النكاح لا بصريحه نحو أن يقول: أريد التزوج،\n⟦1:488⟧\nو \" ما شاء الله كان \"، و \" إنك لنافقة \"، ونحو ذلك، وقوله: ﴿وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا﴾⟪2:235⟫\nقال ابن عباس: وابن جبير والشعبي ومجاهد هو تصريح الوعد بالنكاح، وقال الحسن وجابر، الزني وقال زيد بن مسلم لا تنكحوها في عدتها، واللفظ محتمل، ولكن الأظهر ما قال ابن عباس، لأن ذلك لم يستفد إلا بهذه الآية، فأما خطر الزنى ففي كل حال، والمنع عن التزوج بالمعتدة معقول من غير هذه الآية، ويصح حملها على كل ذلك، فقد نهينا عن جميعه، وقوله ﴿عَلِمَ ٱللَّهُ أَنَّكُمۡ سَتَذۡكُرُونَهُنَّ﴾⟪2:235⟫ أي لما علم رغبتكم فيهن وخوفكم أن يسبقكم إليهن غيركم، أباح لكم التواصل إلى مرادكم بالتعريض وليس النهي عن العزم نهيا عن حكم الضمير، فقد أباح لنا التعريض فضلا عنه، وإنما عنى بت القول، وقوله: ﴿حَتَّىٰ يَبۡلُغَ ٱلۡكِتَٰبُ أَجَلَهُۥۚ﴾⟪2:235⟫ أي تنقضي العدة والكتاب عبارة عن المدة المفروضة أو أريد حكم الكتاب، وقوله: ﴿وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِيٓ أَنفُسِكُمۡ﴾⟪2:235⟫ دل على معنيين، أحدهما: ما في قوله: ﴿يَعۡلَمُ ٱلسِّرَّ وَأَخۡفَى﴾⟪20:7⟫، والثاني: ما في قوله: ﴿إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ﴾⟪12:53⟫، تنبيها أنه علم شرور أنفسكم، ثم حذرنا منه كقوله: ﴿وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ﴾، ثم رجانا غفرانه، وسكن منا بما أنبأنا من حلمه بقوله: ﴿أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ﴾⟪2:235⟫، واللفظان: أعني ﴿وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِيٓ أَنفُسِكُمۡ﴾⟪2:235⟫، وقوله، ﴿وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ﴾⟪2:235⟫ وصف به أولياءه في قوله: ﴿وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ﴾⟪17:57⟫\n⟦1:489⟧"}, {"a": [236], "v": 1, "p": 489, "ev": 1, "ep": 491, "sid": 490, "t": "قوله - عز وجل -:\n﴿لَّا جُنَاحَ عَلَيۡكُمۡ إِن طَلَّقۡتُمُ ٱلنِّسَآءَ مَا لَمۡ تَمَسُّوهُنَّ أَوۡ تَفۡرِضُواْ لَهُنَّ فَرِيضَةٗۚ وَمَتِّعُوهُنَّ عَلَى ٱلۡمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلۡمُقۡتِرِ قَدَرُهُۥ مَتَٰعَۢا بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُحۡسِنِينَ﴾⟪2:236⟫\nالآية (236) - سورة البقرة.\nالمقتر: الفقير، وأصله من ينال القتر، كما أن المترب والمرمل أصلهما من نال التراب والرمل، والقتار ما يحمله الريح من رائحة القدر على العثان والغبار، فدخل قاتر خفيف، كأنه قتر في الخفة، وذلك لقولهم: هو في الخفة هباء، والقترة ناموس الصائد اعتبارا بأنه حافظ لقتار الإنسان أي ريحه، وذلك أن الصائد يجتهد أن يخفي عن الوحش ريحه فصلا عن شخصه لئلا يند عنه،، وأبي قرة لحيته صغيرة الجرم خبيثة الأثر، وتسميتها بذلك على حسب اعتقادهم أن الحية كلما ازدادت سنا وخبثا صغرت جرما وجسما ولهذا قال الشاعر:\nذاهية تصغز منها الأنامل\nوقال: دويهية تصفر منها الأنامل\nفأتى بلفظ التصغيير لما أراد تعظيم الوصف، وكثرة الماس والمماسة في الكناية عن الجماع حتى صار كالصريح، والمتعة اسم لكل ما فيه تمتع أو انتفاع قدرا من الزمان، وعلى ذلك قوله: ﴿وَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ﴾⟪10:98⟫، وقول الشاعر:\n'نما نعمة المرء متعة ...\nوحياة المرء ثوب مستعار\n⟦1:490⟧\nلكن صارت المتعة في تعارف الشرع، لما تخص به المطلقة، واختلف الناس في المتعة، أواجبة هي أم غير واجبة، فإن وحبت، فلأي مطلقة تجب؟، وكم قدرها؟ وبأي الزوجين تعتبر؟ وأما وجوبها فعند ابن أبي ليلى ليست بواجبه على مطلق، بل إن شاء فعل، وإن شاء ترك، وقالت علي: واجبة لكل مطلقة، وقال مالك وليث: \" لا يجيز عليها علي كل حال، وعند الشافعي المطلقات على ثلاثة أضرب، مطلقة قبل الفرض والمسيس، ولها المتعة قولا واحدا، ومطلقة بعد الفرض والمسيس مفوضة كاتبا، وتسمى لها، وفي وجوب المتعة لها قولان، وأما قدرها، فالصحيح أن لأحد له، وإن كان قد قال بعضهم للموسر خادم، وللمعسر خمار وجلباب ونحوهما من الثياب، وقال الشافعي: واستحسن بقدر ثلاثين درهما، وأما اعتبار ذلك بأيهما، فقد قال أبو حنيفة بهما، والأظهر أنها تعتبر بالزوج لتخصيصه في الآية، وقوله ﴿أَوۡ تَفۡرِضُواْ﴾⟪2:236⟫ تقديره، أو لم تفرضوا فهو معطوف على قوله: تماسوهن، وأوفى نحو هذا الموضع يفيد ما يفيد الواو على وجه، وذاك أنه إذا قيل: \" افعل كذا إن جاءك زيد أو عمرو يقتضي أن يفعله إن جاء أحدهما، ولا شك أنه يحتاج أن يفعله إذا جاءا جميعا، لأنه قد جاء أحدهما وزيادة، وعلى هذا قال النحويون: \" جالس الحسين وابن سيرين \" يقتضي أنه إذا جالسهما، فقد امتثل، وعلى هذا قوله- عز وجل: ﴿وَلَا تُطِعۡ مِنۡهُمۡ ءَاثِمًا أَوۡ كَفُورٗا﴾⟪76:24⟫ وقوله: ﴿وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ﴾، فظاهر الآية يقتضي أنه لم يكن مسيس أو لم يكن لها فرض أو لم يكن الأمران، فلها المتعة كالأمثلة المتقدمة، لكن لما حكم لمن فرض لها ولم يمس في الآية التي بعدها صار ذلك كالمستثنى عنه، وكأنه قيل: إذا طلقتموهن ولم يحصل الإمران الفرض والمسيس أو حصل المسيس، ولم يحصل الفرض، فمتعوهن\nإن قيل: ما في قوله ﴿مَا لَمۡ تَمَسُّوهُنَّ﴾⟪2:236⟫ يقتضي الشرط، وذلك يوجب أن رفع الجناح عن المطلق بشرط عدم المماسة وعدم الفرض، ومعلوم أن الجناح مرفوع عن المطلق، مسها، أولم يمسها، فرض أولم يفرض، فما وجه ذلك؟ قيل: القصد بالآية أن الجناح مرفوع بإعطاء المتعة، فكأنه قيل: لا جناح في طلاقها إذا متعها، ودل على ذلك بقوله: ﴿وَمَتِّعُوهُنَّ﴾⟪2:236⟫، وقد علم أن الجناح غير مرفوع عمن لم تمتع إذا طلقها قبل الفرض والمسيس، وقوله: ﴿عَلَى ٱلۡمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلۡمُقۡتِرِ قَدَرُهُۥ﴾⟪2:236⟫ أي قدر ما يحتمل حالاهما ...\nإن قيل: ما وجه تخصيص المحسنين في هذه الآية، والمقتر في قوله: ﴿وَلِلۡمُطَلَّقَٰتِ مَتَٰعُۢ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ﴾⟪2:241⟫، وهلا دل ذلك على أنه غير واجب إن كانت الواجبات من المشروعات لا يختلف فيها المتقي والمحسن وغيرهما، قيل: قد نظر بعض الناس هذا النظر، وقال: لما كان الإحسان قد يكون لما يريد على الواجب، وقد خص بذلك المحسنين دل على أن ذلك حق على المعروف لا إيجاب، وقال أكثرهم: إن ذلك للمحسنين والمتقين لا لتخصيص الإيجاب، بل للتأكيد، وأنه من تمام الإحسان والتقوى، كما أن قوله: ﴿هُدٗى لِّلۡمُتَّقِينَ﴾⟪2:2⟫ ليس بتخصيص أنه لا يهدي به إلا المتقين، لكن يبينه على أن الاهتداء به من تمام التقوى.\n⟦1:491⟧"}, {"a": [237], "v": 1, "p": 491, "ev": 1, "ep": 492, "sid": 492, "t": "قوله - عز وجل -:\n﴿وَإِن طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ وَقَدۡ فَرَضۡتُمۡ لَهُنَّ فَرِيضَةٗ فَنِصۡفُ مَا فَرَضۡتُمۡ إِلَّآ أَن يَعۡفُونَ أَوۡ يَعۡفُوَاْ ٱلَّذِي بِيَدِهِۦ عُقۡدَةُ ٱلنِّكَاحِۚ وَأَن تَعۡفُوٓاْ أَقۡرَبُ لِلتَّقۡوَىٰۚ وَلَا تَنسَوُاْ ٱلۡفَضۡلَ بَيۡنَكُمۡۚ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٌ﴾⟪2:237⟫\nالآية: (237) - سورة البقرة.\nالنصف كل واحد من الجزئين المتساويين من مقدار واحد، وتصور هذه القسمة المستوية، فسمي العدالة نصفا والنصف بين المسنة، والصغيرة كأنها هي التي استوفت نصف العمر والناصف الخادم المبالغ في الخدمة كأنه ينصف صاحبه أي في الخدمة بقدر ما يستوفي عنه من المنفعة، والنصيف للخمار بين الصغيرة والكبيرة، والمنصف ما أعيد إلى النصف بالصبح، والنصيف ضرب من المكيال، لكونه عادمها، أو كونه بين بين ...\n(والذي بيده عقدة النكاح)، قيل: هو الولي الذي كان ما لكان للعقد في الأصل وقيل الزوج الذي هو مالك للعقد في الحال، وهو أولى، لأن الولي يملك العقد، والزوج هو الذي يملك العقدة لأن العقدة اسم للمفعول كضحكه وهزأه، وعفو المرأة أن تترك الهر أو تسامح، وعفو الزوج أن يوفيها كله أو فضلا عما تستحقه من النصف فإن قيل جعل الذي بيده عقدة النكاح للولي، فكيف يصح منه العفو عما تستحقه المرأة، قيل: قد قال الشافعي: إن ذلك مخصوص في الصغيرة إذا كان وليها أباها أو جدها ...\nإن قيل: العفو في الترك لا في الإعطاء، والزوج هو المعطي، فكيف يصح منه العفو؟\nقيل: إن ذلك في العفو عن الشيء لا في العقوبة، وقد يقال: عفي فلان بكذا إذا بذل، والصداق المفروض تستحق المرأة أخذه بالعقد، فإن أخذبه، وإلا ففيي حكم المأخوذ، فإذا عفي به كملا، فكأنه قد عفي عنه، ودل قوله تعالى: ﴿فَنِصۡفُ مَا فَرَضۡتُمۡ﴾⟪2:237⟫ أن المرأة متى فرض لها بمثل العقد، ثم طلقت قبل الدخول، فلها نصف المفروض بخلاف ما قال أبو حنيفة أن المفروض يسقط وتجب المتعة، وقوله: ﴿وَأَن تَعۡفُوٓاْ﴾⟪2:237⟫ وأن كان بالقصد الأول حثا للزوجين على التسامح خطاب عام لهما ولكافة الناس وحث\n⟦1:492⟧\nلهما على استعمال العفو وترك التشرد، وإن بعض ما وجب لك أقرب إلى الهوى، ثم قال: ﴿وَلَا تَنسَوُاْ ٱلۡفَضۡلَ﴾⟪2:237⟫ أعم من العفو، لأنه يتناول ترك ما وجب لك، وإعطاء ما لا يلزمك، ولهذا قيل: \" الفضل فوق العدل \"، وقيل: \" الكرم في الفضل لا في العدل \"، ولما حث فيما تقدم على استعمال العدالة، نبه بقوله: ﴿وَلَا تَنسَوُاْ ٱلۡفَضۡلَ﴾⟪2:237⟫ أي: لا تتركوا الفضل مقتصرين على تحري العدالة."}, {"a": [238], "v": 1, "p": 492, "ev": 1, "ep": 494, "sid": 493, "t": "قوله - عز وجل -:\n﴿حَٰفِظُواْ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ وَقُومُواْ لِلَّهِ قَٰنِتِينَ﴾⟪2:238⟫\nالآية: (238) - سورة البقرة.\nالحفظ والتعقد والتعهد والرعاية والحماية والصيانة متقاربة، لكن الحفظ أعلم ذلك، والتفقد حفظه، أي تفقد وكأنه مطلب في كل حال، بل فقد إشفاقا عليه، والتعهد تجديد العهد به حالا فحالا، والرعاية حفظ ما به قوامه، كرعي الغنم للحماية حفظه عما يريده بسوئه ..\n، والصيانة: صيونة بما تقيه، والوسط معروف يقال بوسط فلان القوم سبطهم، وقد تصور الوسط على وجهين، محمود ومذموم، فاستعمل فيهما، أما المحمود فالمصون من الإفراط والتفريط، كالعدل، ولهذا قيل للعدل الوسط والسواء والنصف، وأما المذموم، فيتصور شيء له طريقان: محمود، ومذموم، فالسالك من الطرف المحمود إلى الطرف المذموم إذا انتهى إلى النصف، فقد فارق المذموم، فكنى به عن الذم، وأما أصل \" القنوت \" القيام على سبيل الخضوع، ولما كان الخضوع في يكون بالدعاء والتضرع، وبالإمساك عن الكلام، ويخفض الصوت، وغض البصر، وبذل المال فنبه بكل واحد من ذلك وسمي الدعاء بعد الركوع قنوتا، والصلاة الوسطى الظهر عن زيد بن ثابت، وابن عمر كأنها اعتبرت بالنهار، وكونها في وسطه، والمغرب عن قبيصة بن دويت، لكونها وسطا بين الركعتين والأربع اللتين بنى عليهما عدد الركعات، والصبح عن جابر، لكونها بين صلاة الليل والنهار، قيل: ولهذا قال: ﴿أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمۡسِ إِلَىٰ غَسَقِ ٱلَّيۡلِ وَقُرۡءَانَ ٱلۡفَجۡرِۖ إِنَّ قُرۡءَانَ ٱلۡفَجۡرِ﴾⟪17:78⟫ أي صلاته، فخصها بالذكر، لكثرة الكسل عنها، إذ قد تحتاج إلى القيام إليها من لذيذ النوم، ولهذا زيد في أذانه: (الصلاة خير من النوم)، وقيل: هو العصر فيما\n⟦1:493⟧\nيروى عن النبي - صلى الله عليه وسلم - وعلي وابن عباس، وهو الأصح، لما روي أن ابن حبيش قال: قلت ليسرة: سلي\nعليا عن الصلاة الوسطى، فقال: كنا نرى أنها صلاة الفجر، حتى سمعت رسول الله - صلى الله عليه وسلم - يوم الخندق\nيقول: \" شغلونا عن الصلاة الوسطى صلاة العصر، ملأ الله قلوبهم أو قبورهم نارا \"، وروي البراء أنه كان يقرأ: \" حافظوا على الصلوات وصلاة العصر \"، ثم نسخ بقوله: الوسطى، وفائدة تخصيصها بالذكر، لأن وقتها في أثناء الأشغال العامة الناس بخلاف سائر الصلوات التي يكون فراغ ما إما قبلها، أو بعدها، ولذلك توعد النبي - صلى الله عليه وسلم - بتركها، فقال: \" من فاتته صلاة العصر فكأنما وتر ماله وأهله \"، واستدل بهذه الآية بعض الشافعية أن الوتر ليس بواجب، لأنه لو كان واجبا لكان أعداد الواجبات ستة، فلم يكن لها وسطى، وقال بعض المتأخرين: الصلاة الوسطى إشارة إلى النوافل المشروعة بين المكتوبات إما قبلها، وإما بعدها وإما قبلها وبعدها، وقال بعضهم:\nعنى بالصلوات أنواعها كلها، فرائضها ونوافلها المؤقتة، والمشروعات عند أسبابها كالخسوفين، والاستسقاء، والنذر، فأمر تعالى بالمحافظة على جميعهما، ثم قال: ﴿وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ﴾⟪2:238⟫ أن الفرائض، ومعنى الوسطى: الشريفة، فخصها بالذكر مع دخولها في العموم، ثم أعقبه بقوله: ﴿وَقُومُواْ لِلَّهِ قَٰنِتِينَ﴾⟪2:238⟫ وبقوله: ﴿فَإِنۡ خِفۡتُمۡ﴾⟪2:239⟫ - تنبيها أن فعلها واجب بحسب الإمكان في جميع الأحوال، والمحافظة عليها مراعاة وقتها وتوفية شرائطها في أدائها كما ذكر في إقامتها في قوله: ﴿وَيُقِيمُونَ ٱلصَّلَوٰةَ﴾.\n⟦1:494⟧\nإن قيل: ما وجه فائدة ذكر المحافظة على الصلاة فيما بين حكمي الطلاق والعدة؟\nوهلا أفرد عن ذلك؟ فإن إفراد كل باب من الحكم أحسن في الترتيب من خلط بعضه ببعض، قيل: أما أولانا: فآيات القرآن منزلة حسب الحاجات، ولهذا قال الكفار:\n﴿لَوۡلَا نُزِّلَ عَلَيۡهِ ٱلۡقُرۡءَانُ جُمۡلَةٗ وَٰحِدَةٗۚ﴾⟪25:32⟫ أعلمهم أنه فعل ذلك ليقوى عليه الصلاة والسلام- على تلقينه وتلقنه فقال: ﴿وَقُرۡءَانٗا فَرَقۡنَٰهُ لِتَقۡرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكۡثٖ وَنَزَّلۡنَٰهُ تَنزِيلٗا﴾⟪17:106⟫، ثم إن الله تعالى لا يخلي شيئا يذكره مما تعلق بالأحكام الدنيوية إلا ويقرنه بحكم أخروي لينبههم إلى مراعاة الآخرة في جميع أحوالهم وأعمالهم، وأنها هي المقصودة بالقصد الأول وسائر ما يتحرى، فلأجلها، على أن ما يرونه موجود هاهنا ومحفوظ، وأبلغ وأحسن مما راعاه أصحاب القوانين، لأنه لما حثهم على العفو ورغبهم في المحافظة عي الفضل، عرفهم أن السلوك إلى التخصيص بذلك هو المحافظة على الصلوات في كل حال، فإن الصلاة هي الآمرة بالمعروف، والناهية عن المنكر، كما قال: ﴿إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۗ﴾⟪29:45⟫، ثم صرف الكلام إلى ذكر ما كان بصدده، فتممه، وهذا النحو من جنس ما يسمى ب التفات المعدود في بديع الكلام .."}, {"a": [239], "v": 1, "p": 494, "ev": 1, "ep": 495, "sid": 495, "t": "قوله تعالى:\n﴿فَإِنۡ خِفۡتُمۡ فَرِجَالًا أَوۡ رُكۡبَانٗاۖ فَإِذَآ أَمِنتُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ﴾⟪2:239⟫\n\" الآية (239) - سورة البقرة ..\nالركوب: كون الشيء فوق أخر، يقال لكل مركوب ركوب، وخص الراكب في تعارف العرف يمتطي البعير، وسمى المطية ركابا، وما يجعل الراكب رجله فيه ركاب، وأركب المهر، بحيث يركب، وتعورف المركب، والمركب فيمن ركب فرس غيره، وفيمن يعجز عن الركوب من قوله: ثم الطيور المركبا والركبة: بهذا الاعتبار سميت، وقيل: \" فرس أركب، أي \" عظيم الركبة، وركبته: أصبت ركبته،\n⟦1:495⟧\nنحو: فأدته ورأسته، وقال: إذا أصبته بركبتك، نحو: بدنته وعنته، أصبته بهما، والمركب كناية عن فرج المرأة، وهو العانة من المرأة، كما كني عن المرأة بمظنة، وقعيدة، لكونها مقتعدة، ورجال: جمع راجل: نحو صحاب وقيام، ويقال.\nنساء رجال، كما يقال: رجال رجال، أمر تعالى بفعل الصلاة على الوجه الممكن.\nوعلى هذا دل قوله: ﴿فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَقۡصُرُواْ مِنَ ٱلصَّلَوٰةِ إِنۡ خِفۡتُمۡ أَن يَفۡتِنَكُمُ ٱلَّذِينَ كَفَرُوٓاْۚ﴾⟪4:101⟫ وعلى هذا قوله: ﴿فَإِذَا قَضَيۡتُمُ ٱلصَّلَوٰةَ فَٱذۡكُرُواْ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِكُمۡۚ﴾⟪4:103⟫ وجعل بعضهم الذكر هاهنا مخصصا بالصلاة، وجعله بعضهم عاما فيه وفي غيره من الأذكار، وحث على ذكره والصلاة كيفما يقتضيه ما علم من الأحكام وسائر العلوم."}, {"a": [240], "v": 1, "p": 495, "ev": 1, "ep": 497, "sid": 496, "t": "قوله- عز وجل:\n﴿وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا وَصِيَّةٗ لِّأَزۡوَٰجِهِم مَّتَٰعًا إِلَى ٱلۡحَوۡلِ غَيۡرَ إِخۡرَاجٖۚ فَإِنۡ خَرَجۡنَ فَلَا جُنَاحَ عَلَيۡكُمۡ فِي مَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ مِن مَّعۡرُوفٖۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ﴾⟪2:240⟫\nالآية: (240) سورة البقرة.\nعامة المفسرين على أن قوله تعالى:\n﴿وَصِيَّةٗ لِّأَزۡوَٰجِهِم﴾⟪2:240⟫ أمر من الله عز وجل- بأن يوصي الرجال للزوجات أن تعمر بعد وفاتهم حولا، وقالوا: اقتضت الآية ثلاثة أحكام: عدة سنة ونفقتها، وسكناها في تركة زوجها مادامت معتدة، وكونها ممنوعة من الخروج، فنسخ منها ما زاد على أربعة أشهر وعشر بالآية المتقدمة، ونسخ وجوب الوصية لها ما به الميراث، ولم يثبت نسخ للخروج، فصار دلك ثابتا في العدة الثانية، وقال بعض المتأخرين:\n⟦1:496⟧\nليست هذه الآية منسوخة ولا تأويلها على ما تصوره، وإنما قوله: (وصية) مصدر في مواضع الحال، أو خبر ابتداء مضمر في موضع الحال في قول من رفع، والآية إخبار عن الجاهلية فيما كانوا يفعلونه، وإبطال لحكمهم في تقديرها: ﴿وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا﴾⟪2:240⟫ موصين لها بمتاع، أي بعطيه على أن لا يخرجن إلى الحول، ﴿فَلَا جُنَاحَ عَلَيۡكُمۡ فِي مَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ﴾⟪2:240⟫، أي لا إثم في إبطال ذلك على ما أمر الله به، وبينه، ودعاكم إليها فهذا توكيد للآية المتقدمة وتنمية أن ما كانوا يفعلونه لا يلزمكم، بل الذي يلزمكم ما بين في الآية المتقدمة، فقوله:\n﴿وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ﴾⟪2:240⟫ مبتدأ، وما بعده إلي قوله: ﴿غَيۡرَ إِخۡرَاجٖۚ﴾⟪2:240⟫ في صلته وفي قوله: ﴿فَإِنۡ خَرَجۡنَ﴾⟪2:240⟫ في موضع الخبر، ودخول الفاء فيه لكون المبتدأ موصولا، نحو: \" الذي يأتيني فله درهم \"، وهذا الوجه صحيح من وجه، حيث اللفظ وعلى ما عليه الحكم، لكن عامة السلف في تفسيرها على ما تقدم، ويوضح ذلك أن امرأة أتت النبي - صلى الله عليه وسلم -، فذكرت أن بنيا لها توفي عنها زوجها اشتكت عينها، وهي تريد أن تكحلها، فقال رسول الله - صلى الله عليه وسلم - الله: \" فقد كانت إحداكن تلبث سنة، ثم ترمي ببعرة عند رأس الحول، فهلا أربعة أشهر وعشرا \"\nوذكر رواية بنت أبي سلمة أن المرأة كانت إذا توفى بها زوجها دخلت خيشا، ولبست شرشابها، ولا تمس طيبا حتى تمر سنة، ثم تؤتى بدابة، حمار أو شاة أو طير، فتقتص له، فعل ما يقتض شيئا إلامات، ثم تخرج فتعطى بعرة فترمى بها، ثم تراجع ما شاءت من طيب أو غيره ..\nإن قيل: لم قال في هذه الآية، وفيما قبلها: ﴿فَلَا جُنَاحَ عَلَيۡكُمۡ فِي مَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ﴾⟪2:240⟫؟، فرفع الجناح عن الرجال فيما فعلن، وذلك يقتضي أن يزر أحدنا وزر الآخرة، وقد قال تعالى: ﴿وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ﴾.\n⟦1:497⟧\nقيل: قد يرون في قراءة ابن مسعود: ﴿فَلَا جُنَاحَ عَلَيۡهِ أَن﴾، والصحيح ما عليه المصاحف، ووجه ذلك أمران:\nأحدهما: أن النساء لما كن تابعات للرجال، وتحرر أمرهم، صار الجناح في كثير مما يفعلن راجعا إليهم إذا لم ينهوهن، ولهذا قال: ﴿قُوٓاْ أَنفُسَكُمۡ وَأَهۡلِيكُمۡ نَارٗا﴾⟪66:6⟫ والتاني: أن ما يشير إليه، فإنهن يفعلن في أنفسهن هو أمر يتعلق بالرجال، فلا يمكنهن أو يساعدوهن وكل موضع اجتمع مذكر ومؤنث أو مخاطب أو غائب، فالحكم في اللفظ للمذكر والمخاطب دون المؤنث والغائب، فلهذا قال: عليكم إن قليل: لم قال هاهنا ﴿مِن مَّعۡرُوفٖۗ﴾⟪2:240⟫، وقال فيما قبله (بالمعروف)، وقال هاهنا: ﴿وَٱللَّهُ عَزِيزٌ حَكِيمٞ﴾⟪2:240⟫، وفي الأول: ﴿وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ﴾؟\nقيل: إن \" من \" والباقي مثل هدا الموضع يتقاربان حكما، وإن كانا يختلفان من حيث العربية تقديرا، فقوله: ﴿مِن مَّعۡرُوفٖۗ﴾⟪2:240⟫ إباحة لجنس الأفعال المعروفة، أي المباحة لجنسه، وقوله: (بالمعروف) في موضوع الحال، وهو إباحة لما فعلته على شريطة تحري المعروف وقال ههنا: لما ذكر ما هو تعريض التغيير أو غيره على التفسير المتأخر، قال: ﴿وَٱللَّهُ عَزِيزٌ حَكِيمٞ﴾⟪2:240⟫ تنبيها أنه تعالى قادر على تغيير ما يغير غير لاحق به مضرة من مخالفتكم له، ولا منفعة في موافقتكم إياه أمره وحكمته في تغييره، وقال في الحكم المقرر عليهم على التأييد، (والله بما تعلمون خبير) - تنبيها أن من قصر فيما رسمه، فمجازى به .."}, {"a": [241], "v": 1, "p": 497, "ev": 1, "ep": 498, "sid": 498, "t": "قوله- عز وجل:\n﴿وَلِلۡمُطَلَّقَٰتِ مَتَٰعُۢ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ﴾⟪2:241⟫ - الآية: (241) - سورة البقرة\nإن قيل: ما وجه تكرير.\n\" ذلك \" وتخصيص \" المتقين \"؟\nقيل: من المفسرين من جعل هذا المتاع للمطلقات عامة على سبيل الاستحباب، لا على الإيجاب،\n⟦1:498⟧\nوقال: أراد الله أن يكون تشريحا على وجه تطيب به نفسها، ويزول عنها ما خامرها مش وحشة الفراق، ومنهم من قال: هو على الإيجاب، وإليه ذهب ابن جبير، وأبو العالية ويكون تخصيص من تقدم ذكرها لتأكيد أمرها، ومنهم من قال: يعني بالمتاع المتعة، وإنما عنى مالها من المهر والسكنى، وأما تخصيص \" المتقين \" فقد تقدم .."}, {"a": [242], "v": 1, "p": 498, "ev": 1, "ep": 499, "sid": 499, "t": "قوله- عز وجل:\n﴿كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ﴾⟪2:242⟫ الآية: (242) سورة البقرة.\nنبه أنه كما بين لكم هذه الأحكام يبين لكم سائر الآيات العقلية والسمعية لتكونوا أقرب إلى استعادة العمل المكتسب وقد تقدم أن أمير المؤمنين قال: العقل عقلان: مطبوع ومسموع ولا يصلح أحدهما إلا بالآخر، فالأول هو الذي يتعلق به صحة التكليف المتناهية بقوله عليه الصلاة والسلام:\n\" إن الله لما خلق العقل، قال له: أقبل، فأقبل، ثم قال له: أدبر، فأدبر، ثم قال: وعزتي وجلالي ما خلقت خلقا أكرم علي منك بك أخذ، وبك أعطي \".\n⟦1:499⟧\nوالثاني: هو الذي قال عليه الصلاة والسلام لعلي: \" يا علي: إذا تقرب الناس إلى خالقهم بالصلاة والصوم، فتقرب إليه بانواع العقل تسيقهم بالدرجات والزلفى عند الناس في الدنيا، وعند الله في الآخرة \" فهذا الثاني هو العقل المشار إليه بقوله تعالى: ﴿لَعَلَّكُمۡ تَعۡقِلُونَ﴾⟪2:242⟫، وهو في الحقيقة الإيمان والتقوى والإخلاص."}];
